('32d50184-f239-59d8-a3ff-7000650b6ba3','bc561419-f9b7-57b9-a32e-b45c46d6f658',1,'verb','B2','S3','W3','[ transitive ]','[{"phrase":"somebody deserves a medal","register":"spoken","definition_en":"used to say that you admire the way someone dealt with a situation or problem","translation":"قبلاً می گفت که شما نحوه برخورد یک نفر با یک موقعیت یا مشکل را تحسین می کنید","example":"You deserve a medal for putting up with Ian’s constant demands.","example_translation":"شما به خاطر تحمل خواسته های همیشگی ایان مستحق یک مدال هستید.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001137596.mp3"}]'::jsonb),
('68cfb3db-6441-5263-8fd8-88e55a277ff1','ae81c342-1b74-5439-91fa-2d051df5c7f5',1,'preposition','B1','S3','W1',null,'[{"phrase":"despite yourself","register":null,"definition_en":"if you do something despite yourself, you do it although you did not intend to","translation":"اگر کاری را با وجود خود انجام دهید، آن را انجام می‌دهید، اگرچه قصد انجام آن را نداشتید","example":"Liz realized that, despite herself, she cared about Edward.","example_translation":"لیز متوجه شد که با وجود خودش، به ادوارد اهمیت می دهد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000820039.mp3"}]'::jsonb),
