('21401763-2c44-5758-8e8d-7b518212f33e','989c25a1-f31e-5bea-ac5e-97e1cb13c4fd',1,'noun','C1',null,'W2','[ countable, uncountable ]','[{"phrase":"be beyond dispute","register":null,"definition_en":"if something is beyond dispute , everyone agrees that it is true or that it really happened","translation":"اگر چیزی غیر قابل بحث باشد، همه قبول دارند که درست است یا واقعاً اتفاق افتاده است","example":"It is beyond dispute that advances in medicine have enabled people to live longer.","example_translation":"قابل بحث نیست که پیشرفت های پزشکی به مردم این امکان را داده است که عمر طولانی تری داشته باشند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001147422.mp3"},{"phrase":"be open to dispute","register":null,"definition_en":"if something is open to dispute , it is not completely certain and not everyone agrees about it","translation":"اگر چیزی قابل بحث باشد، کاملاً قطعی نیست و همه در مورد آن موافق نیستند","example":"His interpretation of the poem is open to dispute.","example_translation":"تفسیر او از شعر محل مناقشه است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001147436.mp3"},{"phrase":"be in dispute","register":null,"definition_en":"if something is in dispute , people are arguing about it","translation":"اگر چیزی مورد مناقشه باشد، مردم در مورد آن بحث می کنند","example":"The facts of the case are still in dispute.","example_translation":"حقایق پرونده هنوز مورد مناقشه است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001962571.mp3"}]'::jsonb),
