('cc7c868c-46c4-53b5-a543-c98b6d1d64d7','4fc1381c-ec6a-548b-8251-dc78575e5632',1,'adjective','B2',null,'W3',null,'[{"phrase":"distant from something","register":null,"definition_en":"different from something or not closely connected with it","translation":"متفاوت از چیزی است یا ارتباط نزدیکی با آن ندارد","example":"The reality of independence was distant from the hopes they had had.","example_translation":"واقعیت استقلال با امیدهایی که داشتند فاصله داشت.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690609.mp3"}]'::jsonb),
