('214cf0f6-c22a-5193-89b7-466143928ec8','0c748172-df65-54f7-ba1b-41ab575eb7df',1,null,null,'spoken & written','a person or animal that has won something','[ countable ]',null,'برنده، قهرمان؛ برنده (جایزه)؛ برنده (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the winner of the Ladies’ Championship","translation":"برنده مسابقات قهرمانی بانوان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630159.mp3"},{"sentence":"Five lucky winners will each receive a signed copy of the album.","translation":"پنج برنده خوش شانس هر کدام یک نسخه امضا شده از آلبوم را دریافت خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630156.mp3"},{"sentence":"As a jockey he rode 10 winners.","translation":"به عنوان یک جوکی او 10 برنده را سوار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000491814.mp3"},{"sentence":"a Nobel prize winner","translation":"برنده جایزه نوبل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000491813.mp3"}]'::jsonb,4),
('1215bb0f-0ab1-508e-9470-dad8c6b4b005','0c748172-df65-54f7-ba1b-41ab575eb7df',2,null,null,'informal','someone or something that is or is likely to be very popular and successful','[ countable ]',null,'کسی یا چیزی که بسیار محبوب و موفق است یا احتمال دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The book has proved to be a winner with young children.","translation":"این کتاب با کودکان خردسال برنده شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000491819.mp3"},{"sentence":"The company seems to be onto a winner (= doing something that is likely to be successful ) .","translation":"به نظر می رسد شرکت برنده است (= انجام کاری که احتمالاً موفقیت آمیز است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630161.mp3"}]'::jsonb,2),
('5f962ed2-a22e-56a5-9f64-21de7d04e9d6','0c748172-df65-54f7-ba1b-41ab575eb7df',3,null,null,'spoken & written','a goal or point that makes someone win a game such as football or tennis','[ singular ]',null,'گل یا امتیازی که باعث می‌شود کسی در بازی‌هایی مانند فوتبال یا تنیس برنده شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Moran scored the winner with only two minutes left.","translation":"موران تنها در دو دقیقه باقی مانده گل برتری را به ثمر رساند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630174.mp3"}]'::jsonb,1),
('889cae52-2ede-5f23-ad55-591758a3663e','0c748172-df65-54f7-ba1b-41ab575eb7df',4,null,null,'spoken & written','the person who gets most of the advantages from a situation','[ countable usually plural ]',null,'شخصی که بیشترین مزیت ها را از یک موقعیت به دست می آورد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In a capitalist society there will always be winners and losers .","translation":"در یک جامعه سرمایه داری همیشه برنده و بازنده وجود خواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630179.mp3"},{"sentence":"The real winners this summer have been the sun cream manufacturers.","translation":"برنده واقعی این تابستان تولیدکنندگان کرم ضد آفتاب بوده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630180.mp3"}]'::jsonb,2),
('133da39e-4778-54cc-a237-f2a198c101a6','a73eeeec-b329-5c06-b5a1-585168528260',1,null,null,'spoken & written','the season after autumn and before spring , when the weather is coldest',null,null,'زمستان، زمستان (فصل)','{}'::text[],'{}'::text[],array['cold That winter was particularly cold.','severe/hard/harsh (= very cold ) In a hard winter, many birds starve.','mild (= not very cold ) Winters here are generally mild.','long (= lasting a long time ) The long winter finally came to an end.','the winter months During the winter months the town is often cut off.','winter coat/shoes (= designed for winter ) I need a new winter coat.','in the depths of winter (= in the middle of the winter ) Even in the depths of winter, the harbour is never completely frozen.','the onset of winter She dreaded the onset of winter.']::text[],'[{"sentence":"Soon it will be winter.","translation":"به زودی زمستان می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001754.mp3"},{"sentence":"It usually snows here in the winter.","translation":"معمولا در زمستان اینجا برف می بارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630218.mp3"},{"sentence":"Fuel supplies could be seriously disrupted this winter.","translation":"عرضه سوخت ممکن است در زمستان امسال به طور جدی مختل شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630223.mp3"}]'::jsonb,3),
('04dd3bf4-f8a4-5951-85fa-2dff9f5b65fa','823887fe-962d-525e-921f-88acc86e8d24',1,null,null,'spoken & written','to spend the winter somewhere',null,null,'برای سپری کردن زمستان در جایی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Last year, over 11,000 Canadians wintered in Arizona.","translation":"سال گذشته بیش از 11000 کانادایی در آریزونا زمستان گذرانی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630228.mp3"}]'::jsonb,1),
('843a75af-a651-5d79-9876-27b9a53e9105','e1070e3b-e28b-546c-b9de-0a41887c0766',1,null,null,'spoken & written','before a certain period of time has passed',null,null,'در مدت، در ظرفِ (زمان)؛ درونِ (مکان)؛ در (حد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We should have the test results back within 24 hours.","translation":"ما باید نتایج آزمایش را ظرف 24 ساعت برگردانیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494384.mp3"},{"sentence":"He fell sick and died within a matter of weeks.","translation":"او بیمار شد و در عرض چند هفته درگذشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841873.mp3"},{"sentence":"Within an hour of our arrival Caroline was starting to complain.","translation":"در عرض یک ساعت از ورود ما، کارولین شروع به شکایت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841874.mp3"},{"sentence":"the enormous success of televised sport within the last twenty years","translation":"موفقیت عظیم ورزش تلویزیونی در بیست سال گذشته","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626721.mp3"},{"sentence":"Within the space of a year, three of the town’s factories have closed down.","translation":"در عرض یک سال، سه کارخانه این شهر تعطیل شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494391.mp3"}]'::jsonb,5),
('c8b27cc9-f34b-52b5-b0a8-9eee95e8764d','e1070e3b-e28b-546c-b9de-0a41887c0766',2,null,null,'spoken & written','less than a certain distance from a particular place',null,null,'کمتر از فاصله معینی از یک مکان خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The invading troops came within 50 miles of Paris.","translation":"نیروهای متجاوز به 50 مایلی پاریس رسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626727.mp3"},{"sentence":"Within a five mile radius of Ollerton there are several pubs and restaurants.","translation":"در شعاع پنج مایلی اولرتون چندین میخانه و رستوران وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841875.mp3"},{"sentence":"We live within easy reach of (= close to ) the shops.","translation":"ما در دسترس (= نزدیک به) مغازه ها زندگی می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841876.mp3"},{"sentence":"Adjust the driver’s seat so that all the controls are within reach (= close enough to touch ) .","translation":"صندلی راننده را طوری تنظیم کنید که همه کنترل ها در دسترس باشند (= به اندازه کافی نزدیک برای لمس).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841881.mp3"},{"sentence":"As she came within sight of the house, she saw two men getting out of a car.","translation":"وقتی به خانه رسید، دو مرد را دید که از ماشین پیاده می شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841889.mp3"}]'::jsonb,5),
('3437acb4-766d-5357-be7a-b5dd128e0975','e1070e3b-e28b-546c-b9de-0a41887c0766',3,null,null,'spoken & written','inside a particular building or area',null,null,'در داخل یک ساختمان یا منطقه خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Prisoners who died were buried within the walls of the prison.","translation":"زندانیانی که می مردند در داخل دیوارهای زندان دفن می شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841890.mp3"},{"sentence":"public footpaths within the national park","translation":"مسیرهای پیاده روی عمومی در پارک ملی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626736.mp3"},{"sentence":"The rooms within were richly furnished.","translation":"اتاق های داخل مبله فراوانی داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841891.mp3"},{"sentence":"Baby rabbits for sale. Enquire within.","translation":"فروش بچه خرگوش. در داخل پرس و جو کنید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841895.mp3"}]'::jsonb,4),
('1d347495-4a95-5812-92e5-144b0bb56f16','e1070e3b-e28b-546c-b9de-0a41887c0766',4,null,null,'spoken & written','inside a society , organization , or group of people',null,null,'درون یک جامعه، سازمان یا گروهی از مردم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There have been a lot of changes within the department since I joined.","translation":"از زمانی که من به این بخش پیوستم، تغییرات زیادی در بخش ایجاد شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494407.mp3"},{"sentence":"an attempt to reform the system from within","translation":"تلاش برای اصلاح نظام از درون","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494410.mp3"}]'::jsonb,2),
('7569dde0-ec0a-54a2-9838-bea30b9fe530','e1070e3b-e28b-546c-b9de-0a41887c0766',5,null,null,'spoken & written','if something stays within a particular limit or set of rules , it does not go beyond that limit',null,null,'اگر چیزی در محدوده یا مجموعه ای از قوانین خاص باقی بماند، از آن حد فراتر نمی رود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We have to operate within a very tight budget.","translation":"ما باید در یک بودجه بسیار محدود عمل کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494414.mp3"},{"sentence":"Security firms have to work strictly within the law.","translation":"شرکت های امنیتی باید به شدت در چارچوب قانون کار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494415.mp3"},{"sentence":"You can go anywhere you want within reason (= within reasonable limits ) .","translation":"شما می توانید در محدوده عقل (= در محدوده معقول) به هر جایی که می خواهید بروید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841896.mp3"}]'::jsonb,3),
('9f6a386e-e633-5a8f-b4ff-9de8e810ef3f','e1070e3b-e28b-546c-b9de-0a41887c0766',6,null,null,'literary','inside a person’s body or mind',null,null,'درون بدن یا ذهن یک فرد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Elaine felt a pain deep within her.","translation":"الین در اعماق وجودش احساس درد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626752.mp3"},{"sentence":"I’m feeling more relaxed within myself.","translation":"در درون خودم احساس آرامش بیشتری می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841901.mp3"}]'::jsonb,2),
('49e8902f-6de0-5568-926c-3a6f6b504ade','e1240e96-dde4-519f-93d2-f1e8dd58f354',1,null,null,'spoken & written','to think about something that you are not sure about and try to guess what is true , what will happen etc',null,null,'متفاوت بودن (از آنچه)؛ متعجب شدن (از)؛ حیرت (حس)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I wonder how James is getting on.","translation":"من تعجب می کنم که جیمز چگونه پیش می رود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495406.mp3"},{"sentence":"What are they going to do now, I wonder ?","translation":"حالا می‌خواهند چه کار کنند، تعجب می‌کنم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495407.mp3"},{"sentence":"I wonder if I’ll recognize Philip after all these years.","translation":"نمی دانم آیا پس از این همه سال فیلیپ را می شناسم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495410.mp3"},{"sentence":"He’s been leaving work early a lot – it makes you wonder , doesn’t it?","translation":"او خیلی زود کار را ترک می کند - این شما را متعجب می کند، اینطور نیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626896.mp3"}]'::jsonb,4),
('c7e84bce-3ac5-5765-b11b-0ee86e735f35','e1240e96-dde4-519f-93d2-f1e8dd58f354',2,null,null,'spoken & written',null,null,'I wonder if/whether','متفاوت بودن (از آنچه)؛ متعجب شدن (از)؛ حیرت (حس)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('b00b4932-0bac-5815-9743-a89454cd8123','e1240e96-dde4-519f-93d2-f1e8dd58f354',3,null,null,'spoken & written',null,null,'I was wondering if/whether','متفاوت بودن (از آنچه)؛ متعجب شدن (از)؛ حیرت (حس)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('2e689550-12e0-5954-8321-9bb2fc5f8165','e1240e96-dde4-519f-93d2-f1e8dd58f354',4,null,null,'spoken & written','to feel surprised and unable to believe something',null,null,'غافلگیر شدن و ناتوانی در باور چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sometimes I wonder about his behaviour.","translation":"گاهی اوقات به رفتار او تعجب می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495437.mp3"},{"sentence":"I wonder how he dares to show his face!","translation":"تعجب می کنم که چطور جرات می کند صورتش را نشان دهد!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495440.mp3"},{"sentence":"I don’t wonder you’re tired.","translation":"من تعجب نمی کنم که شما خسته شده اید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495446.mp3"},{"sentence":"He’ll come back soon enough, I shouldn’t wonder.","translation":"او به زودی برمی گردد، من نباید تعجب کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495452.mp3"}]'::jsonb,4),
('84ea16ac-dad0-53fa-a427-7d883e3388f7','e1240e96-dde4-519f-93d2-f1e8dd58f354',5,null,null,'spoken & written','to doubt or question whether something is true',null,null,'شک کردن یا اینکه آیا چیزی درست است یا خیر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Is she serious?’ ‘I wonder.’","translation":"\"آیا او جدی است؟\" \"من تعجب می کنم.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495457.mp3"},{"sentence":"Sometimes I wonder if he’s got any sense at all!","translation":"گاهی اوقات فکر می کنم که آیا او اصلاً عقل دارد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495460.mp3"}]'::jsonb,2),
('cba255cf-8c92-59c4-80cf-66b2dd8d8019','ba712547-4b5f-568a-806c-99609754bbb2',1,'admiration','تحسین','spoken & written','a feeling of surprise and admiration for something very beautiful or new to you','[ uncountable ]',null,'احساس تعجب و تحسین برای چیزی بسیار زیبا یا جدید برای شما',array['awe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The sight of the Taj Mahal filled us with wonder.","translation":"دیدن تاج محل ما را پر از شگفتی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495472.mp3"},{"sentence":"technological wonders","translation":"شگفتی های تکنولوژیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495477.mp3"},{"sentence":"the Seven Wonders of the World","translation":"عجایب هفتگانه جهان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000495478.mp3"}]'::jsonb,3),
