('d876fa67-6e98-560d-9a0c-e5e41a37ecbc','47d4feef-7b53-5d61-9f55-46f13ee68eb8',1,null,null,'spoken & written','someone who writes books , stories etc, especially as a job',null,null,'نویسنده، کاتب؛ نویسنده (فرد)؛ نویسنده (حرفه)','{}'::text[],'{}'::text[],array['a good/great writer She was a very good writer. Dr Johnson was already a great writer at the age of thirty-five.','a fiction/science-fiction/mystery writer The movie is based on a story by science-fiction writer Phillip K. Dick.','a travel/history/sports etc writer (= someone who writes articles and books about a subject ) This region of Europe does not excite many travel writers.','a prolific writer (= someone who writes a lot of books etc ) He was a prolific writer of everything from poems to essays.','a freelance writer She now works as a freelance writer.']::text[],'[{"sentence":"She’s one of my favourite writers.","translation":"او یکی از نویسندگان مورد علاقه من است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001767.mp3"},{"sentence":"a science-fiction writer","translation":"یک نویسنده علمی تخیلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040316.mp3"},{"sentence":"a well-known writer on American music","translation":"نویسنده مشهور موسیقی آمریکایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040317.mp3"},{"sentence":"a writer of children’s stories","translation":"نویسنده داستان های کودکان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000504866.mp3"}]'::jsonb,4),
('6591406f-c059-58f3-83f1-766aaa702cf1','47d4feef-7b53-5d61-9f55-46f13ee68eb8',2,null,null,'spoken & written','someone who has written something or who writes in a particular way',null,null,'کسی که چیزی نوشته یا به شیوه ای خاص می نویسد','{}'::text[],'{}'::text[],array['a good/great writer She was a very good writer. Dr Johnson was already a great writer at the age of thirty-five.','a fiction/science-fiction/mystery writer The movie is based on a story by science-fiction writer Phillip K. Dick.','a travel/history/sports etc writer (= someone who writes articles and books about a subject ) This region of Europe does not excite many travel writers.','a prolific writer (= someone who writes a lot of books etc ) He was a prolific writer of everything from poems to essays.','a freelance writer She now works as a freelance writer.']::text[],'[{"sentence":"He’s always been a sloppy writer.","translation":"او همیشه یک نویسنده شلخته بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002006724.mp3"},{"sentence":"the writer of the previous message on this topic","translation":"نویسنده پیام قبلی در مورد این موضوع","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002006727.mp3"}]'::jsonb,2),
