('7231c089-4965-5027-a509-b7d4a682f585','f0db9136-ce63-5750-92cf-4e8ac2f37653',1,null,null,'spoken & written','to leave someone, especially someone you are responsible for',null,null,'ترک کردن، رها کردن (کسی یا چیزی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How could she abandon her own child?","translation":"چگونه می توانست فرزند خود را رها کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963493.mp3"}]'::jsonb,1),
('aee868a0-e0d3-50d4-85ec-6f501f948de0','f0db9136-ce63-5750-92cf-4e8ac2f37653',2,null,null,'spoken & written','to go away from a place, vehicle etc permanently, especially because the situation makes it impossible for you to stay',null,null,'برای همیشه از یک مکان، وسیله نقلیه و غیره دور شوید، مخصوصاً به این دلیل که شرایط ماندن شما را غیرممکن می کند',array['leave']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We had to abandon the car and walk the rest of the way.","translation":"مجبور شدیم ماشین را رها کنیم و بقیه راه را پیاده برویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963497.mp3"},{"sentence":"Fearing further attacks, most of the population had abandoned the city.","translation":"بیشتر مردم از ترس حملات بیشتر، شهر را ترک کرده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963498.mp3"}]'::jsonb,2),
('a3b0b12a-91c9-5c82-94fe-34200df3a517','f0db9136-ce63-5750-92cf-4e8ac2f37653',3,null,null,'spoken & written','to stop doing something because there are too many problems and it is impossible to continue',null,null,'انجام کاری را متوقف کنید زیرا مشکلات بسیار زیاد است و ادامه آن غیرممکن است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The game had to be abandoned due to bad weather.","translation":"بازی به دلیل آب و هوای بد مجبور به ترک شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963502.mp3"},{"sentence":"They abandoned their attempt to recapture the castle.","translation":"آنها تلاش خود برای بازپس گیری قلعه را رها کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001732862.mp3"},{"sentence":"Because of the fog they abandoned their idea of driving.","translation":"به دلیل مه، ایده رانندگی خود را کنار گذاشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776706.mp3"}]'::jsonb,3),
('6cc15b94-14f1-5813-b1e0-448aed8be2f5','f0db9136-ce63-5750-92cf-4e8ac2f37653',4,null,null,'spoken & written','to stop having a particular idea, belief , or attitude',null,null,'توقف داشتن یک ایده، باور یا نگرش خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They were accused of abandoning their socialist principles.","translation":"آنها متهم شدند که اصول سوسیالیستی خود را کنار گذاشته اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963506.mp3"},{"sentence":"Rescuers had abandoned all hope of finding any more survivors.","translation":"امدادگران تمام امید خود را برای یافتن بازماندگان دیگر از دست داده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000963509.mp3"}]'::jsonb,2),
