('8fdca21b-a633-5304-9414-83b49f7aac30','e9d50eb1-11be-5810-88b8-c259e86b47b4',2,null,null,'spoken & written','to get or gain something',null,null,'به دست آوردن یا به دست آوردن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The college acquired a reputation for very high standards.","translation":"این کالج به دلیل استانداردهای بسیار بالا شهرت یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000967823.mp3"},{"sentence":"Where did you get that tie?","translation":"آن کراوات را از کجا آوردی؟","audio_url":null},{"sentence":"He soon got a reputation for being unfriendly.","translation":"او به زودی به دلیل غیر دوستانه بودن شهرت پیدا کرد.","audio_url":null}]'::jsonb,3),
