('f9130d7c-cf22-5c3e-b452-3a46c4fc9bde','4779e0f2-e221-5d83-ac45-ee2e02e33046',4,null,null,'spoken & written','used to say that something touches, hits, or rubs a surface',null,null,'معمولاً می‌گفتند چیزی به سطحی برخورد می‌کند، ضربه می‌زند یا می‌مالد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the sound of the rain drumming against my window","translation":"صدای باران که بر پنجره ام می پیچد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000794679.mp3"},{"sentence":"The car skidded and we could hear the crunch of metal against metal.","translation":"ماشین لغزید و صدای کوبیدن فلز به فلز را می شنیدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000794681.mp3"}]'::jsonb,2),
