('d68eed0a-ca90-5db2-b414-c5c122befc67','1aacc58b-7757-5a9b-a458-3216eaea847a',2,null,null,'formal','to arrange or decide a time or place for something to happen',null,null,'ترتیب دادن یا تعیین زمان یا مکانی برای اتفاقی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The committee appointed a day in June for celebrations.","translation":"کمیته یک روز در ماه ژوئن را برای جشن ها تعیین کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000985800.mp3"},{"sentence":"Everyone assembled in the hall at the appointed time (= at the time that had been arranged ) .","translation":"همه در وقت معین (= در ساعتی که مقرر شده بود) در سالن اجتماع کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672400.mp3"}]'::jsonb,2),
('f26214ce-8105-5431-ad3c-c69c7166a28a','130bc141-1b93-562b-a1a9-e25ee46be894',1,null,null,'spoken & written','to officially accept a plan, proposal etc','[ transitive ]',null,'تأیید کردن، تصویب کردن؛ رضایت داشتن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The conference approved a proposal for a referendum.","translation":"کنفرانس پیشنهادی برای همه پرسی را تصویب کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945811.mp3"}]'::jsonb,1),
('006ff775-ce01-5650-b268-c9c9ae39b5a1','130bc141-1b93-562b-a1a9-e25ee46be894',2,null,null,'spoken & written','to think that someone or something is good, right, or suitable','[ intransitive ]',null,'فکر کردن به اینکه کسی یا چیزی خوب، درست یا مناسب است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Catherine’s parents now approve of her marriage.","translation":"والدین کاترین اکنون ازدواج او را تایید می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945818.mp3"},{"sentence":"I don’t approve of cosmetic surgery.","translation":"من جراحی زیبایی را تایید نمی کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672210.mp3"}]'::jsonb,2),
('f1cead30-32d0-5a09-aa30-dcf5e92bbc93','1ba3988b-8234-53e9-af32-102ad1d7c91e',1,null,null,'spoken & written','to organize or make plans for something such as a meeting , party , or trip','[ intransitive, transitive ]',null,'ترتیب دادن، برنامه‌ریزی کردن؛ منظم کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Contact your local branch to arrange an appointment.","translation":"برای تنظیم قرار ملاقات با شعبه محلی خود تماس بگیرید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949427.mp3"},{"sentence":"I’d like to arrange a business loan.","translation":"من می خواهم یک وام تجاری ترتیب دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949428.mp3"},{"sentence":"Have you arranged to meet Mark this weekend?","translation":"آیا قرار ملاقات با مارک این آخر هفته را گذاشته اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949431.mp3"},{"sentence":"Beth arranged a meeting with the marketing director.","translation":"بث با مدیر بازاریابی ملاقاتی ترتیب داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949437.mp3"},{"sentence":"We still have to arrange how to get home.","translation":"ما هنوز باید ترتیبی بدهیم که چگونه به خانه برسیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949443.mp3"},{"sentence":"We had arranged that I would go for the weekend.","translation":"قرار گذاشته بودیم که آخر هفته بروم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664005.mp3"},{"sentence":"Matthew arrived at 2 o''clock as arranged .","translation":"متیو طبق برنامه ساعت 2 رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664006.mp3"}]'::jsonb,7),
('f414f6a9-d89b-581c-bcbb-427316322fd3','1ba3988b-8234-53e9-af32-102ad1d7c91e',2,null,null,'spoken & written','to make it possible for someone to have or do something','[ intransitive, transitive ]',null,'داشتن یا انجام کاری را برای کسی ممکن کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The company will arrange for a taxi to meet you at the airport.","translation":"این شرکت ترتیبی می دهد که تاکسی شما را در فرودگاه ملاقات کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664014.mp3"},{"sentence":"Dave arranged for someone to drive him home.","translation":"دیو ترتیبی داد که کسی او را به خانه برساند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664017.mp3"}]'::jsonb,2),
('23332990-db47-5c8e-bbba-621045a84978','1ba3988b-8234-53e9-af32-102ad1d7c91e',3,null,null,'spoken & written','to put a group of things or people in a particular order or position','[ transitive ]',null,'قرار دادن گروهی از چیزها یا افراد در نظم یا موقعیت خاصی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ben arranged the flowers in a vase.","translation":"بن گل ها را در یک گلدان چید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664018.mp3"},{"sentence":"The list is arranged alphabetically.","translation":"فهرست بر اساس حروف الفبا مرتب شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949451.mp3"},{"sentence":"The children were arranged in lines according to height.","translation":"بچه ها بر حسب قد در خطوط چیده شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949454.mp3"}]'::jsonb,3),
('0eda6f85-e84f-58b1-b5ac-1b94ac7047aa','1ba3988b-8234-53e9-af32-102ad1d7c91e',4,null,null,'spoken & written','to write or change a piece of music so that it is suitable for a particular instrument','[ transitive ]',null,'برای نوشتن یا تغییر یک قطعه موسیقی به گونه ای که برای ساز خاصی مناسب باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a symphony arranged for the piano","translation":"یک سمفونی تنظیم شده برای پیانو","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949461.mp3"}]'::jsonb,1),
('4c50d217-6435-5794-aa60-e6a380c5d874','149bee9c-002e-551a-a0ab-2d8c2574a322',1,null,null,'spoken & written','when someone or something arrives somewhere','[ countable, uncountable ]',null,'رسیدن، ورود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Only the timely arrival of the police prevented the situation from becoming worse.","translation":"فقط آمدن به موقع پلیس از بدتر شدن اوضاع جلوگیری کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949972.mp3"},{"sentence":"Traffic problems account for one third of late arrivals.","translation":"مشکلات ترافیکی یک سوم از دیر رسیدن ها را تشکیل می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664085.mp3"},{"sentence":"Shortly after our arrival in London, Lisa was attacked.","translation":"مدت کوتاهی پس از ورود ما به لندن، لیزا مورد حمله قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664088.mp3"},{"sentence":"A deposit is payable on arrival (= when you arrive ) .","translation":"هنگام ورود (= هنگام ورود) مبلغی پرداخت می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664089.mp3"}]'::jsonb,4),
('5490652c-67f0-51db-8d2b-dee9d9dfc0c6','149bee9c-002e-551a-a0ab-2d8c2574a322',2,null,null,'spoken & written',null,null,'the arrival of something','رسیدن، ورود','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('d44ba844-7428-5a7f-ad11-51c466b8bad0','149bee9c-002e-551a-a0ab-2d8c2574a322',3,null,null,'spoken & written','someone who has just arrived in a place','[ countable ]',null,'کسی که به تازگی به مکانی رسیده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"New arrivals were greeted with suspicion.","translation":"تازه واردها با شک و تردید مورد استقبال قرار گرفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664102.mp3"},{"sentence":"Late arrivals will not be admitted to the theatre.","translation":"ورود دیرهنگام به سالن نمایش داده نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949989.mp3"}]'::jsonb,2),
