('f90c0885-4eb5-54ca-848f-d4f499f00116','46ce1764-c275-583f-80b6-4c0c11d6c520',1,null,null,'spoken & written','to try to do something, especially something difficult',null,null,'تلاش کردن، اقدام کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In this chapter I will attempt to explain what led up to the revolution.","translation":"در این فصل سعی خواهم کرد آنچه را که منجر به انقلاب شد توضیح دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659622.mp3"},{"sentence":"Weather conditions prevented them from attempting the jump.","translation":"شرایط آب و هوایی آنها را از تلاش برای پرش منع کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000925853.mp3"}]'::jsonb,2),
