('ac2b83bf-968b-5a58-8647-965e3f630679','9da2dc11-f454-55ac-8187-56abfff9a72b',1,null,null,'spoken & written','to make someone interested in something, or make them want to take part in something',null,null,'جلب کردن، جذب کردن (علاقه، مخاطب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What attracted me most to the job was the chance to travel.","translation":"چیزی که من را بیشتر به این شغل جذب کرد، فرصت سفر بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000926557.mp3"},{"sentence":"The story has attracted a lot of interest from the media.","translation":"این داستان مورد توجه بسیاری از رسانه ها قرار گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000926560.mp3"}]'::jsonb,2),
('0dce7298-5bc3-5301-af83-81925c4b8079','9da2dc11-f454-55ac-8187-56abfff9a72b',2,null,null,'spoken & written',null,null,'be attracted to somebody','جلب کردن، جذب کردن (علاقه، مخاطب)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5e447eda-b71a-5e2f-8902-2152fdfb57f8','9da2dc11-f454-55ac-8187-56abfff9a72b',3,null,null,'spoken & written','to make someone like or admire something or feel romantically interested in someone',null,null,'وادار کردن کسی چیزی را دوست داشته باشد یا آن را تحسین کند یا به کسی احساس علاقه عاشقانه کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I guess it was his eyes that attracted me first.","translation":"حدس می‌زنم این چشمان او بود که من را جذب کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000926569.mp3"}]'::jsonb,1),
('90ad9450-52db-5a69-8156-202547086c72','9da2dc11-f454-55ac-8187-56abfff9a72b',4,null,null,'spoken & written','to make someone or something move towards another thing',null,null,'وادار کردن کسی یا چیزی به سمت چیز دیگری حرکت کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Leftover food attracts flies.","translation":"باقی مانده غذا مگس ها را جذب می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000926573.mp3"},{"sentence":"low rents designed to attract new businesses to the area","translation":"اجاره کم طراحی شده برای جذب مشاغل جدید به منطقه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000926574.mp3"}]'::jsonb,2),
('69746224-afd8-5373-ae98-7dd59b492a67','a201fb21-b8e1-54d0-9f78-2cc7d72537a5',1,null,null,'spoken & written','the average amount is the amount you get when you add together several quantities and divide this by the total number of quantities',null,null,'متوسط، میانگین؛ معمولی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The age of the candidates ranged from 29 to 49 with an average age of 37.","translation":"سن داوطلبان بین 29 تا 49 سال با میانگین سنی 37 سال بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928493.mp3"},{"sentence":"The average cost of making a movie has risen by 15%.","translation":"میانگین هزینه ساخت یک فیلم 15 درصد افزایش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928494.mp3"},{"sentence":"Last winter was colder than average.","translation":"زمستان گذشته سردتر از حد متوسط ​​بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928495.mp3"},{"sentence":"The cars were being sold at an average price of $11,000.","translation":"این خودروها با قیمت متوسط ​​11000 دلار فروخته می شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644419.mp3"}]'::jsonb,4),
('5e675fc3-e573-597e-9c1b-a042947c5fec','a201fb21-b8e1-54d0-9f78-2cc7d72537a5',2,null,null,'spoken & written','an average amount or quantity is not unusually big or small',null,null,'یک مقدار یا مقدار متوسط ​​به طور غیر معمول بزرگ یا کوچک نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They have an average-size front garden and a large rear garden.","translation":"آنها یک باغ جلویی با اندازه متوسط ​​و یک باغ بزرگ در عقب دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644420.mp3"},{"sentence":"He was in his late twenties and of average height.","translation":"او در اواخر بیست سالگی و قد متوسطی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644423.mp3"}]'::jsonb,2),
('312a27e3-364a-5e19-9e2d-c7231993795e','a201fb21-b8e1-54d0-9f78-2cc7d72537a5',3,null,null,'spoken & written','having qualities that are typical of most people or things',null,null,'داشتن ویژگی هایی که برای اکثر افراد یا چیزها معمول است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The average American has not even thought about next year’s election.","translation":"یک آمریکایی معمولی حتی به انتخابات سال آینده فکر نکرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928506.mp3"},{"sentence":"In an average week I drive about 250 miles.","translation":"در یک هفته به طور متوسط ​​حدود 250 مایل رانندگی می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928507.mp3"}]'::jsonb,2),
('1511da52-70b9-5d19-a881-3ca54e39bf1b','a201fb21-b8e1-54d0-9f78-2cc7d72537a5',4,null,null,'spoken & written','neither very good nor very bad',null,null,'نه خیلی خوب نه خیلی بد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('290b334f-d220-595f-baf6-09efb662aebc','26532852-e5c8-58d3-b759-7b5c2ffcc700',1,null,null,'spoken & written','the amount calculated by adding together several quantities, and then dividing this amount by the total number of quantities','[ countable ]',null,'میانگین، متوسط','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The average of 3,8, and 10 is 7.","translation":"میانگین 3 و 8 و 10 7 است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644426.mp3"},{"sentence":"Each person raised an average of £60 to plant an acre of trees.","translation":"هر فرد به طور متوسط 60 پوند برای کاشت یک هکتار درخت جمع آوری کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644427.mp3"},{"sentence":"The December figures brought the annual average for 2001 up to 10.6 per cent.","translation":"ارقام دسامبر میانگین سالانه سال 2001 را به 10.6 درصد رساند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644428.mp3"}]'::jsonb,3),
('3d339fd4-49eb-5532-9df7-e7e7914b17da','26532852-e5c8-58d3-b759-7b5c2ffcc700',2,null,null,'spoken & written',null,null,'on average','میانگین، متوسط','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('79f17e92-5f9c-5845-bafc-4eb5540bd9fb','26532852-e5c8-58d3-b759-7b5c2ffcc700',3,null,null,'spoken & written','the usual level or amount for most people or things','[ countable, uncountable ]',null,'سطح یا مقدار معمول برای اکثر افراد یا چیزها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Streets in the town centre are wider than the average.","translation":"خیابان‌های مرکز شهر عریض‌تر از میانگین هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644429.mp3"},{"sentence":"The school’s eighth-graders are above average in science.","translation":"دانش‌آموزان کلاس هشتم مدرسه از نظر علمی بالاتر از حد متوسط ​​هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644432.mp3"},{"sentence":"The murder rate in the city has risen to four times the national average .","translation":"نرخ قتل در این شهر به چهار برابر میانگین کشوری رسیده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644433.mp3"}]'::jsonb,3),
('190a081b-e763-5744-ae15-483757b33a70','f67d5186-beca-516a-a014-cbf9474c32e0',1,null,null,'spoken & written','to usually do something or usually happen a particular number of times, or to usually be a particular size or amount','[ linking verb ]',null,'معمولاً کاری را انجام دادن یا معمولاً چند بار اتفاق می افتد، یا معمولاً اندازه یا مقدار خاصی باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The water in the lake is not particularly deep, averaging about 12 metres.","translation":"آب دریاچه عمیق نیست و به طور متوسط حدود 12 متر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928557.mp3"},{"sentence":"The airport averages about a thousand flights a month.","translation":"این فرودگاه به طور متوسط ​​حدود هزار پرواز در ماه دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928558.mp3"},{"sentence":"Inflation averaged just under 2.8% per year.","translation":"تورم به طور متوسط ​​کمتر از 2.8 درصد در سال بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644437.mp3"}]'::jsonb,3),
('16d5b075-1c6e-5f16-94d0-9819e2b40a8a','f67d5186-beca-516a-a014-cbf9474c32e0',2,null,null,'spoken & written','to calculate the average of figures','[ transitive ]',null,'برای محاسبه میانگین ارقام','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The rate of growth was averaged over a period of three years.","translation":"میانگین نرخ رشد در یک دوره سه ساله بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644438.mp3"}]'::jsonb,1),
('028b4bee-c87c-5acc-95a9-390b74937f55','40d09370-a1e2-50b3-9bcb-bf535f2ca1c0',1,null,null,'spoken & written','making you feel embarrassed so that you are not sure what to do or say',null,null,'دشوار و ناخوشایند (شرایطی که خجالت می‌دهد)؛ دست‌وپاگیر',array['difficult']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I hoped he would stop asking awkward questions .","translation":"امیدوارم او از پرسیدن سؤالات ناخوشایند دست بردارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001783354.mp3"},{"sentence":"There was an awkward moment when she didn’t know whether to shake his hand or kiss his cheek.","translation":"لحظه ای ناخوشایند بود که نمی دانست دستش را بفشرد یا گونه اش را ببوسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000929989.mp3"},{"sentence":"an awkward silence","translation":"یک سکوت ناخوشایند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000929990.mp3"},{"sentence":"A laugh can help people over an awkward situation.","translation":"خنده می تواند به افراد در موقعیت های ناخوشایند کمک کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644595.mp3"},{"sentence":"Philip’s remarks put her in an awkward position (= made it difficult for her to know what to do ) .","translation":"اظهارات فیلیپ او را در موقعیتی ناخوشایند قرار داد (= دانستن چه کاری را برای او دشوار کرد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644596.mp3"}]'::jsonb,5),
('97054346-0de4-5d8b-a142-bda7eca9de92','40d09370-a1e2-50b3-9bcb-bf535f2ca1c0',2,null,null,'spoken & written','not relaxed or comfortable',null,null,'آرام یا راحت نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She liked to dance but felt awkward if someone was watching her.","translation":"او دوست داشت برقصد، اما اگر کسی او را تماشا می کرد، احساس ناراحتی می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000930003.mp3"},{"sentence":"Geoff looked uneasy and awkward.","translation":"جف ناآرام و بی دست و پا به نظر می رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000930004.mp3"},{"sentence":"Make sure that the baby is not sleeping in an awkward position.","translation":"اطمینان حاصل کنید که کودک در وضعیت نامناسب نمی خوابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000930005.mp3"}]'::jsonb,3),
('e1f2e93f-d5fa-52c4-a4be-48428955718a','40d09370-a1e2-50b3-9bcb-bf535f2ca1c0',3,null,null,'spoken & written','difficult to do, use, or deal with',null,null,'انجام، استفاده یا مقابله با آن دشوار است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’ll be awkward getting cars in and out.","translation":"ورود و خروج ماشین ها سخت خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000930009.mp3"},{"sentence":"The new financial arrangements were awkward to manage.","translation":"مدیریت ترتیبات مالی جدید سخت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644603.mp3"},{"sentence":"A good carpenter can make a cupboard to fit the most awkward space.","translation":"یک نجار خوب می تواند کمد مناسبی برای نامناسب ترین فضا بسازد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644604.mp3"},{"sentence":"She was afraid he was going to ask an awkward question.","translation":"او می ترسید که او یک سوال ناخوشایند بپرسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644605.mp3"}]'::jsonb,4),
('61ca4b3d-1d78-51c4-a30f-cece25906047','40d09370-a1e2-50b3-9bcb-bf535f2ca1c0',4,null,null,'spoken & written','not convenient',null,null,'راحت نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m sorry to call at such an awkward time but I won’t keep you a minute.","translation":"متاسفم که در چنین زمان ناخوشایندی تماس می گیرم، اما یک دقیقه هم به شما وقت نمی گذارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000929998.mp3"}]'::jsonb,1),
('ab073fee-71e6-5833-a8fd-9c502941ee91','40d09370-a1e2-50b3-9bcb-bf535f2ca1c0',5,null,null,'spoken & written','an awkward person is deliberately unhelpful',null,null,'یک فرد بی دست و پا عمداً مفید نیست',array['difficult']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The staff wanted to go home and they were getting awkward about a meeting starting so late.","translation":"کارکنان می خواستند به خانه بروند و از اینکه یک جلسه خیلی دیر شروع می شد ناراحت می شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000930015.mp3"},{"sentence":"an awkward customer (= person who is difficult and unhelpful )","translation":"یک مشتری بی دست و پا (= شخصی که مشکل و بی فایده است)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644606.mp3"}]'::jsonb,2),
('25e14af2-bb91-54f5-9ea4-4c7b431899f2','74f6f568-0a5c-54ed-b21c-2be55e6e3213',1,'steady','ثابت','spoken & written','a state in which all your weight is evenly spread so that you do not fall','[ uncountable ]',null,'تعادل، توازن؛ مانده حساب؛ ترازو','{}'::text[],'{}'::text[],array['keep your balance (= stay steady ) The sea was so rough that it was hard to keep your balance.','lose your balance (= become unsteady ) She nearly lost her balance as the bus suddenly moved forward.','regain/recover your balance (= become steady again ) He held onto Carrie until he regained his balance.','knock/throw somebody off balance The blow was hard enough to knock him off balance.','a sense of balance A good sense of balance is always useful when you are sailing.']::text[],'[{"sentence":"I lost my balance and fell on my face.","translation":"تعادلم را از دست دادم و روی صورتم افتادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001631357.mp3"}]'::jsonb,1),
('9785894b-514a-5695-a57d-53c32de331b2','74f6f568-0a5c-54ed-b21c-2be55e6e3213',2,'equal amounts','مقادیر مساوی','spoken & written','a state in which opposite forces or influences exist in equal or the correct amounts, in a way that is good','[ singular, uncountable ]',null,'حالتی که در آن نیروها یا تأثیرات متضاد به مقدار مساوی یا درست، به نحوی که خوب است، وجود داشته باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Try to keep a balance between work and play.","translation":"سعی کنید تعادل بین کار و بازی را حفظ کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001631379.mp3"},{"sentence":"Pesticides seriously upset the balance of nature.","translation":"آفت کش ها به طور جدی تعادل طبیعت را بر هم می زنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001000811.mp3"}]'::jsonb,2),
