('c8445342-1e9e-5184-a69b-161b9ed9a888','74f6f568-0a5c-54ed-b21c-2be55e6e3213',11,'mental/emotional health','سلامت روانی/عاطفی','spoken & written','when someone’s mind is healthy and their emotional state is normal','[ singular ]',null,'زمانی که ذهن کسی سالم و وضعیت عاطفی او عادی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The death of her friend had disturbed the balance of her mind .","translation":"مرگ دوستش تعادل ذهنش را به هم ریخته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001631413.mp3"}]'::jsonb,1),
