('abf757d4-e0e7-56f8-b627-8ccd4611e29e','5e86b41a-3ecc-5b2e-92a5-ca16b9b62dad',1,null,null,'spoken & written','to be in or get into a steady position, without falling to one side or the other, or to put something into this position','[ intransitive, transitive ]',null,'توازن داشتن؛ متعادل کردن (بودجه و…)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She was balancing a plate of food on her knees.","translation":"او یک بشقاب غذا را روی زانوهایش متعادل می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001000897.mp3"},{"sentence":"He turned around, balancing awkwardly on one foot.","translation":"چرخید و به طرز عجیبی روی یک پاش تعادل برقرار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001000900.mp3"}]'::jsonb,2),
('110ea9c1-8106-5d25-8e99-836d8f7ab26d','5e86b41a-3ecc-5b2e-92a5-ca16b9b62dad',2,null,null,'spoken & written','to be equal in importance , amount, value, or effect to something that has the opposite effect','[ intransitive, transitive ]',null,'مساوی بودن از نظر اهمیت، مقدار، ارزش یا اثر با چیزی که اثر معکوس دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Job losses in manufacturing were balanced by job increases in the service sector.","translation":"از دست دادن شغل در بخش تولید با افزایش شغل در بخش خدمات متعادل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001631428.mp3"},{"sentence":"just enough sugar to balance the acidity of the fruit","translation":"شکر کافی است تا اسیدیته میوه را متعادل کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001631429.mp3"}]'::jsonb,2),
('0e711f62-7d00-54cf-8948-935156d5d57a','5e86b41a-3ecc-5b2e-92a5-ca16b9b62dad',3,null,null,'spoken & written','to consider the importance of one thing in relation to something else when you are making a decision','[ transitive ]',null,'در هنگام تصمیم گیری اهمیت یک چیز را در رابطه با چیز دیگری در نظر بگیرید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The courts must balance our liberty against the security of the nation.","translation":"دادگاه ها باید بین آزادی ما و امنیت ملت تعادل ایجاد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001000933.mp3"}]'::jsonb,1),
('44008dd5-53fb-5024-9ccd-863b7f78bdea','5e86b41a-3ecc-5b2e-92a5-ca16b9b62dad',4,null,null,'spoken & written',null,null,'balance the budget','توازن داشتن؛ متعادل کردن (بودجه و…)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
