('192f84e2-95c8-510b-9018-69f196514f6f','2b06c5f9-5777-542d-ba39-7ff0bd73e335',13,null,null,'spoken & written','to have a religious faith','[ intransitive ]',null,'برای داشتن ایمان مذهبی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She says those who believe will go to heaven.","translation":"او می گوید کسانی که ایمان دارند به بهشت ​​می روند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001013645.mp3"}]'::jsonb,1),
('1aac6f58-2995-5a5f-a249-cef1fb530ba6','f0b22eee-4f3f-5487-bd1f-90e701aba5c7',1,null,null,'spoken & written','in or to a lower position than something, or directly under something',null,null,'زیر، در زیرِ (مجاورت مستقیم)',array['underneath']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The dolphins disappeared beneath the waves.","translation":"دلفین ها در زیر امواج ناپدید شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000914069.mp3"},{"sentence":"Jo enjoyed feeling the warm sand beneath her feet.","translation":"جو از احساس شن های گرم زیر پاهایش لذت می برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000914070.mp3"},{"sentence":"He was standing on the bridge looking at the river beneath.","translation":"روی پل ایستاده بود و به رودخانه زیر آن نگاه می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841991.mp3"},{"sentence":"Some roofs collapsed beneath the weight of (= unable to support the weight of ) so much snow.","translation":"برخی از سقف ها زیر وزن (= قادر به تحمل وزن ) این همه برف فرو ریختند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841992.mp3"},{"sentence":"They hid under the table.","translation":"آنها زیر میز پنهان شدند.","audio_url":null},{"sentence":"a picture with a caption underneath","translation":"یک عکس با شرح زیر","audio_url":null}]'::jsonb,6),
('7b38a801-b8e4-5804-bd6c-46367be2d1a0','f0b22eee-4f3f-5487-bd1f-90e701aba5c7',2,null,null,'spoken & written','covered by something',null,null,'پوشیده شده توسط چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Shiona shivered beneath the bedclothes.","translation":"شیونا زیر رختخواب می لرزید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001842000.mp3"}]'::jsonb,1),
('bfe3752d-25f4-582a-90d0-222c067f05c7','f0b22eee-4f3f-5487-bd1f-90e701aba5c7',3,null,null,'spoken & written','used to say that someone’s real character or feelings are not shown because their appearance or behaviour is different',null,null,'معمولاً می‌گفتند شخصیت یا احساسات واقعی کسی نشان داده نمی‌شود زیرا ظاهر یا رفتار او متفاوت است',array['underneath']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Dave sensed that something more sinister lay beneath the woman’s cheerful exterior.","translation":"دیو احساس کرد که چیز شوم تری زیر نمای بیرونی شاد زن نهفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000914088.mp3"},{"sentence":"Beneath the surface she was angry.","translation":"در زیر سطح او عصبانی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001671121.mp3"}]'::jsonb,2),
('8b4da2a2-2c0e-5fd6-8471-3fffa5604bd3','f0b22eee-4f3f-5487-bd1f-90e701aba5c7',4,null,null,'spoken & written','not good enough or suitable for someone',null,null,'به اندازه کافی خوب یا مناسب برای کسی نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She acts as if even speaking to us is beneath her.","translation":"او طوری رفتار می کند که گویی حتی صحبت کردن با ما هم زیر دست اوست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001671108.mp3"},{"sentence":"He felt it would be beneath his dignity to comment.","translation":"او احساس می کرد اظهار نظر در شأن او نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001671109.mp3"},{"sentence":"His mother felt he was marrying beneath him (= marrying someone who was not good enough ) .","translation":"مادرش احساس می کرد که او در زیر او ازدواج می کند (= با کسی که به اندازه کافی خوب نیست ازدواج می کند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001671115.mp3"},{"sentence":"I consider such behaviour to be beneath contempt (= so bad that you have no respect for the person involved ) .","translation":"من چنین رفتاری را در حد تحقیر می دانم (= آنقدر بد که برای شخص درگیر احترام قائل نیستی).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001842002.mp3"}]'::jsonb,4),
('55690990-25d7-544a-8150-6b8289dd0302','f0b22eee-4f3f-5487-bd1f-90e701aba5c7',5,null,null,'spoken & written','in a lower, less important rank or job than someone else',null,null,'در رتبه یا شغلی پایین تر و کم اهمیت تر از دیگران',array['below']::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ab7e7221-973b-5e9c-a2cc-e8795f5954a3','dcee9987-ec1d-5832-91c2-53ac4f2ff9a8',1,'advantage','مزیت','spoken & written','an advantage , improvement , or help that you get from something','[ countable, uncountable ]',null,'سود، منفعت، فایده؛ مزایای بیمه','{}'::text[],'{}'::text[],array['have the benefit of something All the hotel rooms have the benefit of a balcony.','get a benefit ( also gain/derive a benefit formal ) In this way, students will gain maximum benefit from their classes.','enjoy the benefits You’ll enjoy all the benefits of being a member.','reap the benefits (= enjoy the advantages of something you have worked hard to get ) He was looking forward to reaping the benefits of all his hard work.','bring/provide benefits The new bridge has brought considerable benefits.','something outweighs the benefits (= something is more important than the benefits ) Make sure that the risks don’t outweigh the benefits.','a great/major/substantial benefit The new system will be a great benefit to the company.','a real benefit To get some real benefit from the exercise, you should continue for at least half an hour.','a direct benefit The money sent has been of direct benefit to the islanders.','a lasting benefit These plans are likely to result in lasting benefit to the whole of our district.','the full benefit of something They will have the full benefit of our facilities.','economic/social/environmental etc benefits Tourism has brought considerable economic benefits to the island.','health benefits Just 30 minutes of moderate daily activity yields health benefits.','mutual benefit (= something good for both people, companies etc involved ) Our two companies are working together for mutual benefit.','potential benefits The potential benefits of the scheme must be weighed against the costs involved.','for your own benefit He used the money for his own benefit, instead of using it to help other people.']::text[],'[{"sentence":"the benefits of contact lenses","translation":"مزایای لنزهای تماسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891971.mp3"},{"sentence":"I never had the benefit of a university education.","translation":"من هرگز از تحصیلات دانشگاهی بهره مند نبودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891978.mp3"},{"sentence":"The new credit cards will be of great benefit to our customers.","translation":"کارت های اعتباری جدید سود زیادی برای مشتریان ما خواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891972.mp3"},{"sentence":"I hope that the decision taken today will be to the benefit of the whole nation.","translation":"امیدوارم تصمیمی که امروز گرفته شده به نفع همه ملت باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891999.mp3"},{"sentence":"Could you just explain again for Mark’s benefit?","translation":"آیا می‌توانید دوباره به نفع مارک توضیح دهید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891998.mp3"},{"sentence":"Most motorists manage without the benefit of four-wheel drive.","translation":"اکثر رانندگان بدون بهره مندی از سیستم چهار چرخ متحرک مدیریت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001892006.mp3"}]'::jsonb,6),
