('4db1fb9d-f00c-512f-9d04-cf031de67024','a70e6b74-763b-5fc4-909e-89a1a30d5941',1,null,null,'spoken & written','if you benefit from something, or it benefits you, it gives you an advantage, improves your life, or helps you in some way','[ intransitive, transitive ]',null,'سود بردن؛ سود رساندن به','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They are working together to benefit the whole community.","translation":"آنها با هم کار می کنند تا به نفع کل جامعه باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653942.mp3"},{"sentence":"Many thousands have benefited from the new treatment.","translation":"هزاران نفر از این درمان جدید بهره مند شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000914263.mp3"},{"sentence":"They would benefit by reducing their labour costs.","translation":"آنها با کاهش هزینه های نیروی کار خود سود خواهند برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653943.mp3"},{"sentence":"I’m sure you’ll benefit greatly from the visit.","translation":"من مطمئن هستم که شما از این بازدید سود زیادی خواهید برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653946.mp3"}]'::jsonb,4),
('87ddc754-78c1-5911-beb5-29685da42e2a','033c3047-7fd9-5220-99d8-7600ae388032',1,null,null,'spoken & written','in or through the space that separates two things, people, or places',null,null,'میانِ، بینِ (دو چیز)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I sat down between Sue and Jane.","translation":"بین سو و جین نشستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016757.mp3"},{"sentence":"a house and stables, with a yard in between","translation":"یک خانه و اصطبل، با یک حیاط در میان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016758.mp3"},{"sentence":"The ball rolled between his feet.","translation":"توپ بین پاهایش غلتید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788566.mp3"}]'::jsonb,3),
('daa35d46-a2e9-5383-88ef-8b8c472b2c82','033c3047-7fd9-5220-99d8-7600ae388032',2,null,null,'spoken & written','in the time that separates two times or events',null,null,'در زمانی که دو زمان یا رویداد را از هم جدا می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Are there any public holidays between Christmas and Easter?","translation":"آیا بین کریسمس و عید پاک تعطیلات رسمی وجود دارد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016762.mp3"},{"sentence":"You shouldn’t eat between meals.","translation":"بین وعده های غذایی نباید غذا بخورید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016763.mp3"},{"sentence":"The team have a lot of work to do between now and Sunday.","translation":"تیم از الان تا یکشنبه کارهای زیادی برای انجام دادن دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788571.mp3"},{"sentence":"A lot of students spend a year abroad in between school and university.","translation":"بسیاری از دانش آموزان یک سال را در خارج از کشور بین مدرسه و دانشگاه می گذرانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788572.mp3"},{"sentence":"I’ve had a few jobs, with long periods of unemployment in between.","translation":"من چند شغل داشتم، با دوره های طولانی بیکاری در این بین.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788573.mp3"}]'::jsonb,5),
('02d5f774-63ec-5bc6-b0c8-9baf0cf61ccd','033c3047-7fd9-5220-99d8-7600ae388032',3,null,null,'spoken & written','within a range of amounts, numbers, distances etc',null,null,'در محدوده ای از مقادیر، اعداد، فواصل و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The project will cost between eight and ten million dollars.","translation":"این پروژه بین هشت تا ده میلیون دلار هزینه خواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016767.mp3"},{"sentence":"Most of the victims were young men between the ages of 16 and 21.","translation":"بیشتر قربانیان مردان جوان بین 16 تا 21 سال بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788574.mp3"}]'::jsonb,2),
('966ec4ed-2219-5220-a89e-c8bde58ab99d','033c3047-7fd9-5220-99d8-7600ae388032',4,null,null,'spoken & written','used to say which two places are joined or connected by something',null,null,'برای گفتن اینکه کدام دو مکان توسط چیزی به هم وصل یا به هم وصل شده اند، استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They’re building a new road between Manchester and Sheffield.","translation":"آنها در حال ساخت یک جاده جدید بین منچستر و شفیلد هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016771.mp3"}]'::jsonb,1),
('c887d0a5-fa01-5fe9-8231-bc6da9489ed6','033c3047-7fd9-5220-99d8-7600ae388032',5,null,null,'spoken & written','used to say which people or things are involved in something together or are connected',null,null,'برای گفتن اینکه چه افراد یا چیزهایی درگیر چیزی با هم هستند یا به هم مرتبط هستند استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the long-standing friendship between Bob and Bryan","translation":"دوستی دیرینه بین باب و برایان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016776.mp3"},{"sentence":"co-operation between the two countries","translation":"همکاری بین دو کشور است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016777.mp3"},{"sentence":"She had overheard a private conversation between two MPs.","translation":"او مکالمه خصوصی دو نماینده مجلس را شنیده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788575.mp3"},{"sentence":"the link between serious sunburn and deadly skin cancer","translation":"ارتباط بین آفتاب سوختگی جدی و سرطان کشنده پوست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001788576.mp3"}]'::jsonb,4),
('a1259c68-473f-5b46-9492-7339b43b601e','033c3047-7fd9-5220-99d8-7600ae388032',6,null,null,'spoken & written','used to say which people or things get, have, or are involved in something that is shared',null,null,'برای گفتن اینکه چه افراد یا چیزهایی به چیزی مشترک می رسند، دارند یا درگیر آن هستند استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tom divided his money between his children.","translation":"تام پولش را بین فرزندانش تقسیم کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016782.mp3"},{"sentence":"Between the four of them they managed to lift her into the ambulance.","translation":"بین چهار نفر آنها موفق شدند او را به داخل آمبولانس ببرند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016783.mp3"},{"sentence":"We collected £17 between us.","translation":"ما بین خودمان 17 پوند جمع آوری کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001016784.mp3"}]'::jsonb,3),
