('4fa2fe51-9ae2-5afb-8c48-ac063c3c9770','def88b53-0a7f-5d9d-899f-12ba89add816',2,null,null,'spoken & written','the largest number or amount of something that is officially allowed',null,null,'بیشترین تعداد یا مقدار چیزی که به طور رسمی مجاز است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a public spending ceiling of £240 billion","translation":"سقف هزینه های عمومی 240 میلیارد پوند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000278.mp3"},{"sentence":"The government imposed a ceiling on imports of foreign cars.","translation":"دولت برای واردات خودروهای خارجی سقف تعیین کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001067579.mp3"}]'::jsonb,2),
