('575ea472-e0e7-5f33-b166-a23fb7029c11','f98d7c12-883a-5a48-913d-95f301e49073',5,null,null,'spoken & written','used to talk about a particular person, thing, group of things etc without naming them or describing them exactly','[ only before noun ]',null,'برای صحبت در مورد یک شخص، چیز، گروهی از چیزها و غیره بدون نام بردن یا توصیف دقیق آنها استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The library’s only open at certain times of day.","translation":"کتابخانه فقط در ساعات خاصی از روز باز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659185.mp3"},{"sentence":"I promised to be in a certain place by lunchtime.","translation":"قول دادم تا ناهار در یک مکان خاص باشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659186.mp3"},{"sentence":"There are certain things I just can’t discuss with my mother.","translation":"چیزهایی هست که من نمی توانم با مادرم صحبت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659187.mp3"},{"sentence":"the expectation of a certain kind of behaviour","translation":"انتظار نوع خاصی از رفتار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659190.mp3"},{"sentence":"Extra funding may be available in certain circumstances.","translation":"ممکن است در شرایط خاصی بودجه اضافی در دسترس باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659193.mp3"}]'::jsonb,5),
