('e03909fc-c153-597a-9f11-c421eb318282','8a54602d-c2f2-5b4b-88c6-ec10ba693cf3',1,null,null,'spoken & written',null,null,'certain of somebody/something',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('2bc8d23e-b0f7-5624-afd0-b79df64254e6','c73e5229-0a96-5b8c-b737-7696303468f6',1,'television','تلویزیون','spoken & written','a television station and all the programmes that it broadcasts',null,null,'کانال (تلویزیون)؛ آبراه؛ مجرا؛ راه','{}'::text[],'{}'::text[],array['a television channel NTV is Russia’s leading television channel.','a news/movie/sports etc channel What’s on the movie channel tonight?','a satellite channel (= using signals sent from a machine in space ) CNN and other satellite channels','a cable channel (= using signals sent through a wire ) ABC announced its plans for a new cable channel.','a terrestrial channel (= not using satellite ) Channel 5 is the newest terrestrial channel in the UK.','a digital channel (= using electronic signals sent out in the form of numbers ) You can’t record one digital channel while watching another.','a commercial channel (= paid for by people advertising on it ) On commercial channels they have advertisement breaks.','change channels Use the remote control to change channels.','switch channels He kept switching channels.','launch a channel (= start a channel broadcasting on TV ) In 1994, SKY launched two new channels.','watch a channel The kids are always watching the cartoon channel.','a channel broadcasts something All the channels are broadcasting the match live.','channel-hop (= keep changing from one channel to another ) I usually start channel-hopping when the adverts are on.']::text[],'[{"sentence":"the news on Channel 4","translation":"اخبار شبکه 4","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071232.mp3"},{"sentence":"The kids are watching cartoons on the Disney Channel.","translation":"بچه ها در کانال دیزنی در حال تماشای کارتون هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667214.mp3"},{"sentence":"What channel is ‘ER’ on?","translation":"''ER'' در چه کانالی است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071233.mp3"},{"sentence":"He changed channels to watch the basketball game.","translation":"او برای تماشای بازی بسکتبال کانال را عوض کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667215.mp3"}]'::jsonb,4),
