('ec1d8939-ebe3-552e-861b-315e333901e0','fcc75165-a622-53dc-8a6f-a05d978ae540',1,null,null,'spoken & written','to control and direct something such as money or energy towards a particular purpose',null,null,'برای کنترل و هدایت چیزی مانند پول یا انرژی به سمت یک هدف خاص',array['direct']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Most of his energy was channeled into writing and lecturing.","translation":"بیشتر انرژی او صرف نوشتن و سخنرانی می شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880090.mp3"},{"sentence":"Profits are channelled to conservation groups.","translation":"سود به گروه های حفاظت هدایت می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666894.mp3"},{"sentence":"The famine relief money was channelled through the UN.","translation":"پول کمک به قحطی از طریق سازمان ملل ارسال شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880093.mp3"}]'::jsonb,3),
('9f58dd52-7e58-5d49-a2aa-2b837909fdd7','fcc75165-a622-53dc-8a6f-a05d978ae540',2,null,null,'spoken & written','to control or direct people or things to a particular place, work, situation etc',null,null,'برای کنترل یا هدایت افراد یا چیزها به مکان، کار، موقعیت خاص و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Women were likely to be channeled into jobs as teachers or nurses.","translation":"احتمالاً زنان به شغل معلمی یا پرستاری هدایت می‌شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666902.mp3"},{"sentence":"Drugs from government pharmacies were being channeled into illegal drug markets.","translation":"داروها از داروخانه های دولتی به بازارهای غیرقانونی دارو هدایت می شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666903.mp3"}]'::jsonb,2),
('e4ea981a-8eeb-5386-9dfd-e38b99ed4f0f','fcc75165-a622-53dc-8a6f-a05d978ae540',3,null,null,'spoken & written','to cut a long deep line in something',null,null,'بریدن یک خط عمیق طولانی در چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Water had channelled grooves in the rock.","translation":"آب شیارهایی را در سنگ ایجاد کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880097.mp3"}]'::jsonb,1),
('399406a6-3b57-53ee-88ee-8e758112d973','fcc75165-a622-53dc-8a6f-a05d978ae540',4,null,null,'spoken & written','to send water through a passage',null,null,'برای ارسال آب از طریق یک گذرگاه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"An efficient irrigation system channels water to the crops.","translation":"یک سیستم آبیاری کارآمد آب را به محصولات کشاورزی هدایت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000880101.mp3"}]'::jsonb,1),
('0bd5efa6-4758-5100-8167-51b5c1b5cd2c','fcc75165-a622-53dc-8a6f-a05d978ae540',5,null,null,'spoken & written','to allow a spirit to come into your body and speak through you, or to tell people a message that you have received in this way',null,null,'اجازه دهید روحی وارد بدن شما شود و از طریق شما صحبت کند یا به مردم پیامی را که از این طریق دریافت کرده اید بگویید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She claims to channel the spirit of a 2,000-year-old hunter.","translation":"او ادعا می کند که روح یک شکارچی 2000 ساله را هدایت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666907.mp3"}]'::jsonb,1),
