('3510061b-8e68-5b54-8206-e1370dbd5392','327cccb1-158a-5a90-a74c-92db206a4384',1,null,null,'spoken & written','a common farm bird that is kept for its meat and eggs','[ countable ]',null,'مرغ، جوجه؛ مرغ (خوراکی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('676a0093-d088-5a7f-81c3-d5dcd5d8c289','327cccb1-158a-5a90-a74c-92db206a4384',2,null,null,'spoken & written','the meat from this bird eaten as food','[ uncountable ]',null,'گوشت این پرنده به عنوان غذا خورده می شود','{}'::text[],'{}'::text[],array['fresh (= recently killed and not frozen ) Is the chicken fresh?','frozen We never buy cheap frozen chicken.','free-range (= from a chicken that moved around outside and ate naturally ) All the chicken we serve is free-range.','roast chicken (= cooked in an oven ) For dinner we''re having roast chicken.','fried chicken (= cooked in oil ) They filled their plates with fried chicken.','skinless chicken (= with the skin removed ) For this recipe, you will need a two pounds of skinless chicken.','chicken breast/thigh/wing Chop the chicken breast into pieces.','a chicken piece (= a chicken breast, leg, thigh or wing ) You will need two chicken pieces per person.','chicken drumsticks (= the lower part of chicken legs ) party food, such as sandwiches and chicken drumsticks','a chicken sandwich/salad/pie etc I''ll make a chicken pie with the leftovers.','stuff a chicken (= fill a chicken with a mixture of onion, lemon, herbs etc )','carve a chicken (= cut up a whole chicken that has been cooked )']::text[],'[{"sentence":"roast chicken","translation":"مرغ کباب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000756372.mp3"},{"sentence":"fried chicken","translation":"مرغ سرخ شده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001834118.mp3"},{"sentence":"chicken soup","translation":"سوپ مرغ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001075468.mp3"}]'::jsonb,3),
('ffc00e6a-0ff3-5a7b-9a90-6cc3e7f1604f','327cccb1-158a-5a90-a74c-92db206a4384',3,null,null,'informal','someone who is not at all brave','[ countable ]',null,'کسی که اصلا شجاع نیست',array['coward']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Don’t be such a chicken!","translation":"این جوجه نباش!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001075479.mp3"}]'::jsonb,1),
('32768276-bf00-510a-b7d3-828d79906754','327cccb1-158a-5a90-a74c-92db206a4384',4,null,null,'spoken & written','a game in which children do something dangerous , for example stand on a railway line when a train is coming, and try to be the one who continues doing it for the longest time','[ uncountable ]',null,'بازی ای که در آن کودکان کار خطرناکی انجام می دهند، مثلاً در هنگام آمدن قطار روی خط راه آهن می ایستند و سعی می کنند کسی باشند که طولانی ترین زمان به انجام آن ادامه دهد.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
