('d0816ce8-b27d-5c9c-a156-449819dbf356','327cccb1-158a-5a90-a74c-92db206a4384',7,null,null,'spoken & written',null,null,'somebody’s chickens have come home to roost','مرغ، جوجه؛ مرغ (خوراکی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('98004786-ad34-5667-9095-2c0b15fe9687','18363bb1-81ea-556b-bff1-18065a492d23',1,null,null,'spoken & written','to decide at the last moment not to do something you said you would do, because you are afraid',null,'chicken out','در آخرین لحظه تصمیم بگیرید که کاری را که گفته اید انجام ندهید، زیرا می ترسید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You’re not chickening out, are you?","translation":"تو نمیخوای بیرون، درسته؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001676172.mp3"}]'::jsonb,1),
('f9a07f0b-cf34-51ad-ab2f-a110de3730e7','fe5ab96c-9a7d-5f06-a89c-a0f9fde54c6f',1,null,null,'spoken & written','not brave enough to do something',null,null,'آنقدر شجاع نیست که کاری انجام دهد',array['cowardly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Dave’s too chicken to ask her out.","translation":"دیو آنقدر مرغ است که از او بخواهد بیرون برود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000882646.mp3"}]'::jsonb,1),
('014ae5e3-6cec-52dc-ba5f-31c952d63c87','37e36e8c-619c-501f-888d-4d19d4461b96',1,null,null,'spoken & written','a path that forms a circle around an area, or a journey along this path',null,null,'مدار، مسیر دوری؛ مدار الکتریکی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We did a circuit of the old city.","translation":"ما یک مدار از شهر قدیمی انجام دادیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001077929.mp3"}]'::jsonb,1),
('ca218d37-f496-558f-923d-89a1e56e831a','37e36e8c-619c-501f-888d-4d19d4461b96',2,null,null,'spoken & written','a track that cars, motorbike s etc race around',null,null,'مسیری که ماشین‌ها، موتورها و غیره در آن مسابقه می‌دهند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1a5cf73e-0e29-59dc-b30e-5ee61482f9ee','37e36e8c-619c-501f-888d-4d19d4461b96',3,null,null,'spoken & written',null,null,'the tennis/lecture/cabaret etc circuit','مدار، مسیر دوری؛ مدار الکتریکی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0acc5898-4a70-5696-b80a-367d1dc8d90b','37e36e8c-619c-501f-888d-4d19d4461b96',4,null,null,'spoken & written','the complete circle that an electric current travels',null,null,'دایره کاملی که یک جریان الکتریکی طی می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an electrical circuit","translation":"یک مدار الکتریکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694201.mp3"}]'::jsonb,1),
('bc3ac560-d232-5bc7-9a5f-a597e5a482d8','37e36e8c-619c-501f-888d-4d19d4461b96',5,null,null,'spoken & written','a regular trip around an area made by a judge or a religious leader , so that a court of law or church can meet in several different places',null,null,'یک سفر منظم در اطراف یک منطقه که توسط یک قاضی یا یک رهبر مذهبی انجام می شود، به طوری که یک دادگاه قانونی یا کلیسا می تواند در چندین مکان مختلف تشکیل جلسه دهد.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a circuit judge","translation":"یک داور مدار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694205.mp3"},{"sentence":"a circuit preacher","translation":"یک واعظ مدار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694206.mp3"}]'::jsonb,2),
('e5b6bf89-65a1-55ac-973c-cf7f443472e7','37e36e8c-619c-501f-888d-4d19d4461b96',6,null,null,'spoken & written',null,null,'do circuits','مدار، مسیر دوری؛ مدار الکتریکی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('daa4099e-f8fa-5ef4-9ae2-0ef4833e4a3b','bbcb0459-9282-5f43-bc59-6213e17e68c5',1,null,null,'spoken & written','someone who lives in a particular town , country, or state',null,'senior citizen','شهروند، تبعه؛ اهل شهر','{}'::text[],'{}'::text[],array['a good citizen One of the aims of education is to produce good citizens.','a law-abiding citizen (= never breaking the law ) Most of the people in this town are law-abiding citizens.','a respectable/decent citizen (= good and honest ) There are gangs on the streets who are terrorizing respectable citizens.','an upstanding/upright citizen (= honest and responsible ) The rest of his family are honest upright citizens.','a model citizen (= a very good one ) His neighbours described him as a model citizen.','an ordinary citizen ( also a regular citizen American English ) The government is not aware of the views of ordinary citizens.','a senior citizen (= someone over 60 years old, or someone who has retired ) There are special clubs for senior citizens.','somebody’s fellow citizens (= people who live in the same town, country etc as you ) 70% of our fellow citizens live in poverty.','a private citizen (= an ordinary citizen without a public position ) Laws exist to protect private citizens.','a leading/prominent citizen (= an important one ) The protests were led by leading citizens in the community.']::text[],'[{"sentence":"We need our schools to teach students to be good citizens.","translation":"ما به مدارسمان نیاز داریم که به دانش آموزان بیاموزند که شهروند خوبی باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694055.mp3"},{"sentence":"The mayor urged citizens to begin preparing for a major storm.","translation":"شهردار از شهروندان خواست تا برای یک طوفان بزرگ آماده شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694056.mp3"}]'::jsonb,2),
('61217392-0062-5f84-b2ed-f0b64aa46a9a','bbcb0459-9282-5f43-bc59-6213e17e68c5',2,null,null,'spoken & written','someone who legally belongs to a particular country and has rights and responsibilities there, whether they are living there or not',null,null,'کسی که قانوناً به یک کشور خاص تعلق دارد و حقوق و وظایفی در آنجا دارد، خواه در آنجا زندگی کند یا نه.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"At the time, there were over 2,000 British citizens living in Iraq.","translation":"در آن زمان بیش از 2000 شهروند بریتانیایی در عراق زندگی می کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694058.mp3"}]'::jsonb,1),
('752b95d5-c748-5c2b-82d0-735e7166b246','bbcb0459-9282-5f43-bc59-6213e17e68c5',3,null,null,'spoken & written',null,null,'second-class citizen','شهروند، تبعه؛ اهل شهر','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
