('eb3af50d-4013-5509-b1d4-263f84a996fd','ffc88c90-c7a3-51ea-a839-6a4c3e8d2e23',1,null,null,'spoken & written','if you combine two or more different things, or if they combine, they begin to exist or work together','[ intransitive, transitive ]',null,'ترکیب کردن، یکجا کردن؛ هم‌افزا شدن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Augustine was later to combine elements of this philosophy with the teachings of Christianity.","translation":"آگوستین بعدها قرار بود عناصر این فلسفه را با آموزه های مسیحیت ترکیب کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695265.mp3"},{"sentence":"Diets are most effective when combined with exercise.","translation":"رژیم های غذایی زمانی موثرتر هستند که با ورزش ترکیب شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872280.mp3"},{"sentence":"A number of factors have combined to create this difficult situation.","translation":"تعدادی از عوامل دست به دست هم داده اند تا این وضعیت دشوار را ایجاد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872277.mp3"},{"sentence":"Ruth hesitated, uncertain of how to combine honesty and diplomacy in her answer.","translation":"روت مردد بود و مطمئن نبود که چگونه صداقت و دیپلماسی را در پاسخ خود ترکیب کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872274.mp3"},{"sentence":"The combined effects of the war and the drought resulted in famine.","translation":"اثرات ترکیبی جنگ و خشکسالی منجر به قحطی شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695274.mp3"}]'::jsonb,5),
('4dd4d199-2307-5d07-96a2-0f0650c6db03','ffc88c90-c7a3-51ea-a839-6a4c3e8d2e23',2,null,null,'spoken & written','to have two or more different features or qualities at the same time','[ transitive ]',null,'داشتن دو یا چند ویژگی یا کیفیت مختلف به طور همزمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Good carpet wool needs to combine softness with strength.","translation":"پشم فرش خوب نیاز به ترکیب نرمی و استحکام دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695283.mp3"}]'::jsonb,1),
('f81c7b96-c0a3-52d8-8fe5-3a8ac7b0e350','ffc88c90-c7a3-51ea-a839-6a4c3e8d2e23',3,null,null,'spoken & written','if two or more different substances combine, or if you combine them, they mix or join together to produce a new single substance','[ intransitive, transitive ]',null,'اگر دو یا چند ماده مختلف با هم ترکیب شوند، یا اگر آنها را ترکیب کنید، آنها با هم مخلوط می شوند یا به هم می پیوندند تا یک ماده واحد جدید تولید کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Different amino acids combine to form proteins.","translation":"اسیدهای آمینه مختلف با هم ترکیب می شوند و پروتئین ها را تشکیل می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872294.mp3"},{"sentence":"Combine all the ingredients in a large bowl.","translation":"تمام مواد را در یک کاسه بزرگ با هم ترکیب کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001412491.mp3"},{"sentence":"Steel is produced by combining iron with carbon.","translation":"فولاد از ترکیب آهن با کربن تولید می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872300.mp3"}]'::jsonb,3),
('94f6fd67-cdf2-57af-a2bd-8d3c4982aa48','ffc88c90-c7a3-51ea-a839-6a4c3e8d2e23',4,null,null,'spoken & written','to do two different activities at the same time','[ transitive ]',null,'برای انجام همزمان دو فعالیت مختلف','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Many people enjoy combining a holiday with learning a new skill.","translation":"بسیاری از مردم از ترکیب تعطیلات با یادگیری یک مهارت جدید لذت می برند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872307.mp3"},{"sentence":"the problems facing women who wish to combine a career and family","translation":"مشکلات پیش روی زنانی که می خواهند شغل و خانواده را ترکیب کنند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872310.mp3"}]'::jsonb,2),
('fea3ad70-abbd-510f-894e-adece4e56ef0','ffc88c90-c7a3-51ea-a839-6a4c3e8d2e23',5,null,null,'spoken & written','if two or more groups, organizations etc combine, or if you combine them, they join or work together in order to do something','[ intransitive, transitive ]',null,'اگر دو یا چند گروه، سازمان و غیره با هم ترکیب شوند، یا اگر آنها را ترکیب کنید، برای انجام کاری به یکدیگر می پیوندند یا با هم کار می کنند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ten British and French companies combined to form the Channel Tunnel Group.","translation":"ده شرکت انگلیسی و فرانسوی با هم ترکیب شدند تا گروه تونل کانال را تشکیل دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695290.mp3"},{"sentence":"University zoologists and government vets are combining forces (= working together ) to investigate the disease.","translation":"جانورشناسان دانشگاه و دامپزشکان دولتی در حال ترکیب نیروها (= کار با هم) برای بررسی این بیماری هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695294.mp3"}]'::jsonb,2),
('31b13509-014a-50ee-8c35-134f6378c278','f5eaab80-c864-5a96-872e-4031700854e5',1,null,null,'spoken & written','a machine used by farmers to cut grain , separate the seeds from it, and clean it',null,null,'ماشینی که کشاورزان برای بریدن دانه، جدا کردن دانه ها از آن و تمیز کردن آن استفاده می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('3a1ac2da-fe3b-5a58-bd43-3d5e9b2db14f','f5eaab80-c864-5a96-872e-4031700854e5',2,null,null,'spoken & written','a group of people, businesses etc who work together',null,null,'گروهی از افراد، مشاغل و غیره که با هم کار می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The factory was sold to a British combine after the war.","translation":"این کارخانه پس از جنگ به یک کمباین انگلیسی فروخته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000872692.mp3"}]'::jsonb,1),
('5e75cc09-cb6b-5a2f-bd45-9383fb8619c4','142f4859-5fed-5703-a2bb-0de49f422343',1,'physical','فیزیکی','spoken & written','a feeling of being physically relaxed and satisfied , so that nothing is hurting you, making you feel too hot or cold etc','[ uncountable ]',null,'آسایش، راحتی؛ تسلی‌خاطر؛ احساس راحتی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"All our sports shoes are designed for comfort and performance.","translation":"تمام کفش های ورزشی ما برای راحتی و عملکرد طراحی شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094619.mp3"},{"sentence":"The temperature was too low for comfort.","translation":"دما برای راحتی خیلی پایین بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695604.mp3"},{"sentence":"I dress for comfort, not fashion.","translation":"من برای راحتی لباس می پوشم نه مد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094610.mp3"},{"sentence":"Alan was very reluctant to leave the warmth and comfort of the fire.","translation":"آلن خیلی تمایلی به ترک گرما و راحتی آتش نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695608.mp3"},{"sentence":"Upstairs is a more intimate bar where guests can relax in comfort.","translation":"در طبقه بالا یک بار صمیمی‌تر وجود دارد که مهمانان می‌توانند در آن راحت استراحت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695611.mp3"},{"sentence":"Now you can watch your favorite movies in the comfort of your own home.","translation":"اکنون می توانید فیلم های مورد علاقه خود را در راحتی در خانه خود تماشا کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094616.mp3"}]'::jsonb,6),
('209f28e7-f460-555c-b56b-1c7882010c88','142f4859-5fed-5703-a2bb-0de49f422343',2,'emotional','احساسی','spoken & written','if someone or something gives you comfort, they make you feel calmer , happier , or more hopeful after you have been worried or unhappy','[ uncountable ]',null,'اگر کسی یا چیزی به شما آرامش دهد، پس از نگرانی یا ناراحتی شما را آرام تر، شادتر یا امیدوارتر می کند.','{}'::text[],'{}'::text[],array['take comfort from something The family has taken comfort from the support of friends.','draw/derive comfort from something formal (= take comfort from something ) Economists have been quick to draw comfort from the latest figures.','find/take comfort in something He had been through a similar experience and she found comfort in that.','offer (somebody) comfort Volunteers are available to offer comfort and advice.','give (somebody) comfort It was impossible to give her any comfort.','bring (somebody) comfort Religious belief can bring comfort during times of stress.','provide comfort Talking about your problems may provide some comfort.','seek comfort (= look for comfort ) People come to us seeking comfort and guidance.','great comfort Your letters have been a great comfort to me.','cold/small comfort (= not much comfort ) The tax changes will provide cold comfort to people living on a pension.','a word of comfort He tried to find some words of comfort that would help her.','a source of comfort Some people eat as a source of comfort.','a crumb of comfort (= a very small amount ) ‘You’re no worse than the rest, ’ the football coach said, trying to offer me a crumb of comfort.','if it’s any comfort (= used to say something that may make someone less worried or unhappy ) If it’s any comfort, you very nearly passed the exam.','comfort food (= food that you eat to make you feel relaxed and happy ) I find pasta and cheese is a great comfort food.']::text[],'[{"sentence":"Whenever he was upset, he would turn to her for comfort and advice.","translation":"هر وقت ناراحت می شد برای آرامش و نصیحت به او مراجعه می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695616.mp3"},{"sentence":"a book which offers comfort and help to the parents of children with cancer","translation":"کتابی که به والدین کودکان سرطانی آرامش و کمک می کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094595.mp3"},{"sentence":"The knowledge that Cara was safe gave him some comfort.","translation":"آگاهی از اینکه کارا در امان است کمی به او آرامش داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695617.mp3"},{"sentence":"My faith has been a source of great comfort over the years.","translation":"ایمان من در طول سال ها منبع آرامش بزرگی بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695620.mp3"},{"sentence":"He drew comfort from her warm support.","translation":"او از حمایت گرم او آرامش گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094598.mp3"},{"sentence":"You can take some comfort in the fact that you did your best.","translation":"شما می توانید با این واقعیت که تمام تلاش خود را انجام داده اید، آرامش داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695628.mp3"},{"sentence":"It was no comfort to think he might be as frightened as she was.","translation":"خیال اینکه او ممکن است مثل او ترسیده باشد، راحت نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695629.mp3"},{"sentence":"Well, if it’s any comfort, I don’t think he’ll try again.","translation":"خوب، اگر راحت باشد، فکر نمی کنم او دوباره تلاش کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695633.mp3"}]'::jsonb,8),
('8e069ec3-cf43-585a-a7b6-be964c0c8ca0','142f4859-5fed-5703-a2bb-0de49f422343',3,'somebody/something that helps','کسی / چیزی که کمک می کند','spoken & written','someone or something that helps you feel calmer, happier, or more hopeful after you have been worried or unhappy','[ countable ]',null,'کسی یا چیزی که به شما کمک می کند بعد از نگرانی یا ناراحتی احساس آرامش، شادی یا امیدواری بیشتری داشته باشید.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Louisa’s been a great comfort to me since Mary died.","translation":"لوئیزا از زمان مرگ مری برای من آرامش بزرگی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094650.mp3"},{"sentence":"It’s a comfort to know there’s someone to keep an eye on the kids.","translation":"اینکه بدانیم کسی هست که حواسش به بچه ها باشد راحت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094656.mp3"}]'::jsonb,2),
('22ebfedf-1024-5818-9b72-ad4144073108','142f4859-5fed-5703-a2bb-0de49f422343',4,'money/possessions','پول / دارایی','spoken & written','a way of living in which you have all the money and possessions that you need or want','[ uncountable ]',null,'راهی برای زندگی که در آن همه پول و دارایی مورد نیاز یا می خواهید را در اختیار داشته باشید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"When Dad died, he left us both enough to live in comfort for the rest of our lives.","translation":"وقتی پدر فوت کرد، آنقدر ما را ترک کرد که تا آخر عمر در راحتی زندگی کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695641.mp3"},{"sentence":"He was used to a life of comfort.","translation":"او به یک زندگی راحت عادت کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695645.mp3"}]'::jsonb,2),
('1b07404a-975b-53df-a01e-aa324e62ac8b','142f4859-5fed-5703-a2bb-0de49f422343',5,null,null,'spoken & written',null,null,'comforts','آسایش، راحتی؛ تسلی‌خاطر؛ احساس راحتی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
