('615aab7f-1d13-5bd9-bede-31b0465b9732','142f4859-5fed-5703-a2bb-0de49f422343',7,null,null,'spoken & written',null,null,'cold/small comfort','آسایش، راحتی؛ تسلی‌خاطر؛ احساس راحتی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('e735d186-5b44-528b-a052-823d35cd7167','af765693-9ce6-55ca-ac88-6d543b3d2783',1,null,null,'spoken & written','to make someone feel less worried, unhappy, or upset , for example by saying kind things to them or touching them',null,null,'ایجاد احساس نگرانی، ناراحتی یا ناراحتی کمتر به کسی، برای مثال با گفتن کلمات محبت آمیز به او یا لمس کردن آنها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Within hours of the news, Helen arrived to comfort her heartbroken friend.","translation":"چند ساعت پس از این خبر، هلن برای دلداری از دوست دلشکسته خود رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695330.mp3"},{"sentence":"He longed to take her in his arms and comfort her.","translation":"آرزو داشت او را در آغوش بگیرد و دلداریش دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695334.mp3"},{"sentence":"Mr Aston’s father was last night being comforted by relatives.","translation":"پدر آقای استون دیشب توسط بستگانش دلداری می‌داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695335.mp3"},{"sentence":"She comforted herself with the thought that it would soon be spring.","translation":"او با این فکر که به زودی بهار می شود خود را آرام می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695338.mp3"}]'::jsonb,4),
('e23101ad-fad7-5595-944b-9149fbca1c44','d3454ae1-454e-585d-9e86-34963bd989bd',1,null,null,'spoken & written','a type of fabric conditioner (= liquid for making clothes feel soft ) , sold in the UK',null,null,'نوعی نرم کننده پارچه (= مایعی برای نرم کردن لباس ها) که در بریتانیا به فروش می رسد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9812b002-402f-5f5a-81fd-cc083f98df3b','dc823d2e-3695-56ef-8226-75765580c2ca',1,'control','کنترل کنید','spoken & written','the control of a group of people or a situation','[ uncountable ]',null,'فرماندهی، کنترل؛ دستور؛ فرمان (صوتی)','{}'::text[],'{}'::text[],array['be in command of something The Colonel showed that he was in complete command of the situation.','the chain/line of command (= a system of passing decisions from people at the the top to the bottom ) Our company has a traditional management chain of command.','have command Athens had command of the oceans.','take command (= begin controlling a group or situation ) Captain Kent took command of the Emergency Control Centre.','assume command formal (= start to be in charge of a group of people ) He assumed command of all the troops in the Washington area.','put/place somebody in command A third goal put Brazil in command of the game.','lose command The enemy was losing command of the situation.','be relieved of your command formal (= lose your military position because you have done something wrong ) The General was relieved of his command due to misconduct.','complete/full command Their fighters had full command of the air over Pearl Harbor.','military command A large area was already under US military command.','joint command (= shared by two people, countries etc ) Russia and Ukraine had joint command over the Fleet.','sole command (= not shared with anyone ) He was in sole command of a small military unit.','a command structure (= the way in which a military organization is organized into ranks ) Each of our national defence forces has its own command structure.']::text[],'[{"sentence":"troops under the command of General Roberts","translation":"نیروهای تحت فرماندهی ژنرال رابرتز","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094825.mp3"},{"sentence":"Lieutenant Peters was now in command.","translation":"ستوان پیترز اکنون فرمانده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695723.mp3"},{"sentence":"He felt fully in command of the situation .","translation":"او احساس می کرد که بر اوضاع مسلط است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094822.mp3"},{"sentence":"The fire officer took command, ordering everyone to leave the building.","translation":"افسر آتش نشانی فرمان را به دست گرفت و به همه دستور داد که ساختمان را ترک کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695727.mp3"},{"sentence":"Each congressman has a large staff at his command (= available to be used ) .","translation":"هر نماینده کنگره یک ستاد بزرگ به فرمان خود دارد (= در دسترس برای استفاده).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094833.mp3"},{"sentence":"By 1944, Fletcher had command of a B-17 bomber and a ten-man crew.","translation":"در سال 1944، فلچر فرماندهی یک بمب افکن B-17 و یک خدمه ده نفره را داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000346.mp3"}]'::jsonb,6),
('0463d428-ced6-51ff-9a9d-6b8fc6b0cad5','dc823d2e-3695-56ef-8226-75765580c2ca',2,'order','سفارش دهید','spoken & written','an order that should be obeyed','[ countable ]',null,'دستوری که باید رعایت شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Shoot when I give the command .","translation":"وقتی دستور دادم شلیک کن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094813.mp3"}]'::jsonb,1),
