('192feef4-e963-5401-8971-7530d13116dd','dc823d2e-3695-56ef-8226-75765580c2ca',5,'military','نظامی','spoken & written','a part of an army , navy etc that is controlled separately and has a particular job','[ countable ]',null,'بخشی از ارتش، نیروی دریایی و غیره که به طور جداگانه کنترل می شود و شغل خاصی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"pilots of the Southern Air Command","translation":"خلبانان فرماندهی هوایی جنوب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094844.mp3"},{"sentence":"the Army High Command","translation":"فرماندهی عالی ارتش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094848.mp3"},{"sentence":"The army command is considering a ceasefire.","translation":"فرماندهی ارتش در حال بررسی آتش بس است.","audio_url":null},{"sentence":"The army command are considering a ceasefire.","translation":"فرماندهی ارتش در حال بررسی آتش بس است.","audio_url":null}]'::jsonb,4),
