('2af811cd-992d-51fd-8c0e-aca185ef3119','d983b35e-5d6e-51a8-8224-531f611a61a6',1,'order','سفارش دهید','spoken & written','to tell someone officially to do something, especially if you are a military leader , a king etc','[ intransitive, transitive ]',null,'اینکه به کسی رسماً بگویید کاری انجام دهد، به خصوص اگر یک رهبر نظامی، یک پادشاه و غیره هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Captain Picard commanded the crew to report to the main deck.","translation":"کاپیتان پیکارد به خدمه دستور داد تا به عرشه اصلی گزارش دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094886.mp3"},{"sentence":"The General commanded that the regiment attack at once.","translation":"ژنرال دستور داد که فوراً هنگ حمله کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094889.mp3"}]'::jsonb,2),
('83b954a6-2709-5895-a189-4781ed91ba19','d983b35e-5d6e-51a8-8224-531f611a61a6',2,'lead the military','ارتش را رهبری کند','spoken & written','to be responsible for giving orders to a group of people in the army, navy etc','[ intransitive, transitive ]',null,'مسئولیت دادن دستور به گروهی از افراد ارتش، نیروی دریایی و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He commands the 4th Battalion.","translation":"او فرماندهی گردان چهارم را بر عهده دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094896.mp3"}]'::jsonb,1),
('4af4a217-3016-571e-b360-b8d28f945405','d983b35e-5d6e-51a8-8224-531f611a61a6',3,'deserve and get','سزاوار و بدست آوردن','spoken & written','to get something such as respect or attention because you do something well or are important or popular','[ transitive ]',null,'برای به دست آوردن چیزی مانند احترام یا توجه به دلیل اینکه کاری را به خوبی انجام می دهید یا مهم یا محبوب هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Philip was a remarkable teacher, able to command instant respect.","translation":"فیلیپ معلم برجسته ای بود که می توانست فوراً احترام بگذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094902.mp3"},{"sentence":"Which graduates command the highest salaries?","translation":"کدام فارغ التحصیلان بالاترین حقوق را دارند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695765.mp3"}]'::jsonb,2),
('4650e305-5b0d-590d-9d46-24bbdec45cab','d983b35e-5d6e-51a8-8224-531f611a61a6',4,'control','کنترل کنید','spoken & written','to control something','[ transitive ]',null,'کنترل کردن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The party that commands a majority of seats in Parliament forms the government.","translation":"حزبی که اکثریت کرسی های پارلمان را در اختیار دارد، دولت را تشکیل می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094910.mp3"}]'::jsonb,1),
('9fa7b329-a78b-5997-bc0d-8b70a9b28a8d','d983b35e-5d6e-51a8-8224-531f611a61a6',5,'view','مشاهده کنید','spoken & written','if a place commands a view , you can see something clearly from it','[ transitive ]',null,'اگر مکانی به یک نما فرمان دهد، می توانید چیزی را به وضوح از آن ببینید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Ramses Hilton commands a magnificent view of Cairo.","translation":"Ramses Hilton دارای منظره ای باشکوه از قاهره است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001094916.mp3"}]'::jsonb,1),
('37b6171d-83ce-50a8-b2af-8d79fc085e80','58a8530f-c93c-582a-afdd-70dc0569dad7',1,null,null,'spoken & written','an opinion that you express about someone or something','[ countable, uncountable ]',null,'نظر، دیدگاه؛ اظهار نظر؛ تذکر',array['remark']::text[],'{}'::text[],array['make a comment Everyone was making appreciative comments about the delicious food.','have a comment (= want to make a comment ) Do you have any comments on that, David?','pass (a) comment British English (= give an opinion ) He looked at my photos but he didn’t pass comment.','invite comment(s) (= ask people to give an opinion ) The website invites comments from people who visit it.','welcome comments (= be glad to hear people’s opinions ) We would welcome your comments and suggestions.','receive comments It is very helpful to receive comments from the public.','a brief/quick comment I just want to make a very brief comment.','a helpful/constructive comment (= one that helps you make progress ) Pay close attention to your teacher’s constructive comments.','a positive/negative comment There were some very positive comments in the report.','a critical comment The school has received critical comments from inspectors.','(a) fair comment (= a criticism that is reasonable ) I accepted as fair comment 90% of what he said.','a snide comment (= unkind and made in a secret or indirect way ) She made some really snide comments about you when you weren’t here.','a disparaging/derogatory comment (= criticizing someone or something in an unpleasant way ) Never make disparaging comments about a colleague’s work.','a scathing/damning comment (= a very critical one ) There were a lot of scathing comments about the film.','an appreciative comment (= showing that you think something is good or nice ) Appreciative comments may improve your staff’s performance.','a sarcastic comment (= in which you say the opposite of what you mean, as an unkind joke ) I tried to stay calm, despite his sarcastic comments.','a casual comment (= not very serious or important ) I only made a casual comment about finding the work a bit boring.','a passing comment (= a quick comment made without thinking about it very carefully ) She got upset about a passing comment I made about her clothes.','a shrewd comment (= good at judging people or situations ) His newspaper article is always full of shrewd comments.','a wry comment (= saying that something is bad in an amusing way ) ‘Perhaps the food could be improved, ’ was the wry comment of one prisoner.','a bitter comment (= an angry one ) Several pensioners passed some bitter comments.','a public comment The jury are forbidden from making public comments.']::text[],'[{"sentence":"his comments about asylum seekers","translation":"نظرات او در مورد پناهجویان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695394.mp3"},{"sentence":"He was fined for making abusive comments to the referee.","translation":"او به دلیل اظهارات توهین آمیز به داور جریمه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695395.mp3"}]'::jsonb,2),
('b5511c12-6734-544f-81d4-6bc689990b03','58a8530f-c93c-582a-afdd-70dc0569dad7',2,null,null,'spoken & written','criticism or discussion of something someone has said or done','[ uncountable ]',null,'انتقاد یا بحث از چیزی که کسی گفته یا انجام داده است','{}'::text[],'{}'::text[],array['make a comment Everyone was making appreciative comments about the delicious food.','have a comment (= want to make a comment ) Do you have any comments on that, David?','pass (a) comment British English (= give an opinion ) He looked at my photos but he didn’t pass comment.','invite comment(s) (= ask people to give an opinion ) The website invites comments from people who visit it.','welcome comments (= be glad to hear people’s opinions ) We would welcome your comments and suggestions.','receive comments It is very helpful to receive comments from the public.','a brief/quick comment I just want to make a very brief comment.','a helpful/constructive comment (= one that helps you make progress ) Pay close attention to your teacher’s constructive comments.','a positive/negative comment There were some very positive comments in the report.','a critical comment The school has received critical comments from inspectors.','(a) fair comment (= a criticism that is reasonable ) I accepted as fair comment 90% of what he said.','a snide comment (= unkind and made in a secret or indirect way ) She made some really snide comments about you when you weren’t here.','a disparaging/derogatory comment (= criticizing someone or something in an unpleasant way ) Never make disparaging comments about a colleague’s work.','a scathing/damning comment (= a very critical one ) There were a lot of scathing comments about the film.','an appreciative comment (= showing that you think something is good or nice ) Appreciative comments may improve your staff’s performance.','a sarcastic comment (= in which you say the opposite of what you mean, as an unkind joke ) I tried to stay calm, despite his sarcastic comments.','a casual comment (= not very serious or important ) I only made a casual comment about finding the work a bit boring.','a passing comment (= a quick comment made without thinking about it very carefully ) She got upset about a passing comment I made about her clothes.','a shrewd comment (= good at judging people or situations ) His newspaper article is always full of shrewd comments.','a wry comment (= saying that something is bad in an amusing way ) ‘Perhaps the food could be improved, ’ was the wry comment of one prisoner.','a bitter comment (= an angry one ) Several pensioners passed some bitter comments.','a public comment The jury are forbidden from making public comments.']::text[],'[{"sentence":"The speech received much comment in the press.","translation":"این سخنرانی با نظرات بسیاری در مطبوعات مواجه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000873256.mp3"}]'::jsonb,1),
('5f238857-a575-5721-bdce-34410df22946','58a8530f-c93c-582a-afdd-70dc0569dad7',3,null,null,'spoken & written',null,null,'be a comment on something','نظر، دیدگاه؛ اظهار نظر؛ تذکر','{}'::text[],'{}'::text[],array['make a comment Everyone was making appreciative comments about the delicious food.','have a comment (= want to make a comment ) Do you have any comments on that, David?','pass (a) comment British English (= give an opinion ) He looked at my photos but he didn’t pass comment.','invite comment(s) (= ask people to give an opinion ) The website invites comments from people who visit it.','welcome comments (= be glad to hear people’s opinions ) We would welcome your comments and suggestions.','receive comments It is very helpful to receive comments from the public.','a brief/quick comment I just want to make a very brief comment.','a helpful/constructive comment (= one that helps you make progress ) Pay close attention to your teacher’s constructive comments.','a positive/negative comment There were some very positive comments in the report.','a critical comment The school has received critical comments from inspectors.','(a) fair comment (= a criticism that is reasonable ) I accepted as fair comment 90% of what he said.','a snide comment (= unkind and made in a secret or indirect way ) She made some really snide comments about you when you weren’t here.','a disparaging/derogatory comment (= criticizing someone or something in an unpleasant way ) Never make disparaging comments about a colleague’s work.','a scathing/damning comment (= a very critical one ) There were a lot of scathing comments about the film.','an appreciative comment (= showing that you think something is good or nice ) Appreciative comments may improve your staff’s performance.','a sarcastic comment (= in which you say the opposite of what you mean, as an unkind joke ) I tried to stay calm, despite his sarcastic comments.','a casual comment (= not very serious or important ) I only made a casual comment about finding the work a bit boring.','a passing comment (= a quick comment made without thinking about it very carefully ) She got upset about a passing comment I made about her clothes.','a shrewd comment (= good at judging people or situations ) His newspaper article is always full of shrewd comments.','a wry comment (= saying that something is bad in an amusing way ) ‘Perhaps the food could be improved, ’ was the wry comment of one prisoner.','a bitter comment (= an angry one ) Several pensioners passed some bitter comments.','a public comment The jury are forbidden from making public comments.']::text[],'[]'::jsonb,0),
('5d429791-9c6b-5626-a202-5bfcad6a3861','117d98b9-7440-5d24-9ace-162ed99fc01d',1,null,null,'spoken & written','to express an opinion about someone or something',null,null,'اظهار نظر کردن؛ تذکر دادن؛ شرح دادن (پخش زنده)',array['remark']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"People were always commenting on his size.","translation":"مردم همیشه در مورد اندازه او نظر می دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000873278.mp3"},{"sentence":"Smith’s lawyer commented that the decision was ‘outrageous’.","translation":"وکیل اسمیت اظهار داشت که این تصمیم \"ظالمانه\" بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000873281.mp3"}]'::jsonb,2),
('65e053b9-3d87-5d61-b788-579e97d7760f','e2e1f5d3-876a-5389-9bda-39b4e329e906',1,'business','کسب و کار','spoken & written','a business organization that makes or sells goods or services','[ countable ]',null,'شرکت، بنگاه؛ همراهی؛ مهمانان',array['business','firm']::text[],'{}'::text[],array['a computer/phone/oil etc company an international oil company','a manufacturing/shipping/publishing etc company I’m working for a printing company at the moment.','a large/big company She has a senior position in a large manufacturing company.','a small company His father is the director of a small company.','an international company (= with offices in different countries ) She works for a major international company.','a multinational company (= with offices in many countries ) Within ten years the business grew into a huge multinational company.','a private company (= not owned by the government ) There are many tiny private companies.','a state-owned company (= owned by the government )','a public/listed company (= offering its shares for sale on the stock exchange )','a limited company (= one whose owners only have to pay a limited amount if it gets into debt )','a subsidiary company (= owned or controlled by a larger company )','the parent company (= the one that owns or controls a smaller one )','a local company The new development will bring more business to local companies.','a reputable company (= with a good reputation ) Choose a reputable building company to do the work.','work for a company How long have you been working for your present company?','join a company (= become an employee ) I joined the company ten years ago.','run/manage a company Nick runs a property company.','set up/start/form a company Two years later he started his own software company.','found/establish a company The company was founded in 1993 by William J. Nutt.','take over a company (= buy it and run it ) The company was taken over by the management in a £32.5 million deal.','a company grows/expands The company has expanded year on year.','a company goes bankrupt/goes out of business (= stops doing business after losing too much money )','a company fails (= goes bankrupt ) His audio equipment company failed in the mid 1980s.','a company goes bust informal (= goes bankrupt )','a company goes to the wall informal (= goes bankrupt )','a company goes into liquidation (= is closed and sold in order to pay its debts )','company policy It is not company policy to give that information.','a company director/executive He earns a huge amount of money as a senior company executive.','a company car (= that your company gives you to use )']::text[],'[{"sentence":"Which company do you work for?","translation":"برای کدام شرکت کار می کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691237.mp3"},{"sentence":"I called the phone company about the bill.","translation":"در مورد قبض با شرکت تلفن تماس گرفتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001939789.mp3"},{"sentence":"The company was set up just after the war.","translation":"این شرکت درست پس از جنگ راه اندازی شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001939780.mp3"},{"sentence":"The company directors have awarded themselves a massive pay increase.","translation":"مدیران شرکت افزایش دستمزد گسترده ای را به خود اختصاص داده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001939804.mp3"},{"sentence":"The company makes machine parts.","translation":"این شرکت قطعات ماشین آلات را تولید می کند.","audio_url":null},{"sentence":"The company make machine parts.","translation":"این شرکت قطعات ماشین آلات را تولید می کند.","audio_url":null}]'::jsonb,6),
('699336e7-aba6-5a1e-99e9-344f401b9a3a','e2e1f5d3-876a-5389-9bda-39b4e329e906',2,'other people','افراد دیگر','spoken & written','when you are with other people and not alone','[ uncountable ]',null,'وقتی با دیگران هستید و تنها نیستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The two men enjoy each other’s company .","translation":"این دو مرد از همراهی یکدیگر لذت می برند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097027.mp3"},{"sentence":"Rita’s husband is away for the week, so I thought I’d go over and keep her company (= be with her so that she doesn’t feel lonely ) .","translation":"شوهر ریتا یک هفته دور است، بنابراین فکر کردم که بروم و با او همراهی کنم (= با او باشم تا احساس تنهایی نکند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097030.mp3"},{"sentence":"Come over for dinner – I could use the company (= would like to be with other people ) .","translation":"برای شام بیا - می توانم از شرکت استفاده کنم (= دوست دارم با افراد دیگر باشم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691264.mp3"},{"sentence":"James is good company (= is a cheerful person who is enjoyable to be with ) .","translation":"جیمز شرکت خوبی است (= فردی شاد است که از بودن با او لذت می برد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691269.mp3"},{"sentence":"Bessie was glad to have the dog as company.","translation":"بسی خوشحال بود که سگ را همراهی می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097036.mp3"},{"sentence":"I felt nervous in the company of such an important man.","translation":"در جمع چنین مرد مهمی احساس عصبی می کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691274.mp3"},{"sentence":"He’s performing in company with saxophonist Ernie Watts.","translation":"او در شرکت با ساکسیفونیست ارنی واتس اجرا می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097044.mp3"}]'::jsonb,7),
('7f334987-2bb2-514b-9414-f8b45b1fd03e','e2e1f5d3-876a-5389-9bda-39b4e329e906',3,'guests','مهمانان','spoken & written','people who are visiting you in your home','[ uncountable ]',null,'افرادی که در خانه شما را ملاقات می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It looks like the Hammills have company .","translation":"به نظر می رسد Hammills شرکت دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097053.mp3"},{"sentence":"We’re expecting company this evening.","translation":"امروز عصر منتظر شرکت هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097057.mp3"}]'::jsonb,2),
('4ff17b1e-cbbd-5e41-96f9-989472443606','e2e1f5d3-876a-5389-9bda-39b4e329e906',4,'friends','دوستان','spoken & written','your friends or the group of people you spend time with','[ uncountable ]',null,'دوستانتان یا گروهی از افرادی که با آنها وقت می گذرانید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"People judge you by the company you keep (= the people you spend time with ) .","translation":"مردم شما را بر اساس شرکتی که دارید (= افرادی که با آنها وقت می گذرانید) قضاوت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097070.mp3"},{"sentence":"Things began to go wrong when he got into bad company .","translation":"وقتی وارد یک شرکت بد شد همه چیز شروع به خراب شدن کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691286.mp3"}]'::jsonb,2),
('d58e4e16-2001-5f1a-8759-63f2cc7963fb','e2e1f5d3-876a-5389-9bda-39b4e329e906',5,'performers','مجریان','spoken & written','a group of actors , dancers , or singers who work together','[ countable ]',null,'گروهی از بازیگران، رقصندگان یا خوانندگانی که با هم کار می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a theatre company","translation":"یک شرکت تئاتر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691294.mp3"},{"sentence":"a touring company","translation":"یک شرکت توریستی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691297.mp3"},{"sentence":"the Kirov Ballet Company","translation":"شرکت باله کیروف","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097087.mp3"}]'::jsonb,3),
('a6398e3d-d5b6-5934-be1c-b0b3f600c1f1','e2e1f5d3-876a-5389-9bda-39b4e329e906',6,null,null,'spoken & written',null,null,'be in good company','شرکت، بنگاه؛ همراهی؛ مهمانان','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('908a6eab-d03b-5e1a-9dd2-c6dad5eac5e8','e2e1f5d3-876a-5389-9bda-39b4e329e906',7,'GROUP','گروه','formal','a group of people who are together in the same place, often for a particular purpose or for social reasons','[ uncountable ]',null,'گروهی از مردم که اغلب برای یک هدف خاص یا به دلایل اجتماعی در یک مکان با هم هستند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He glanced around at the assembled company .","translation":"نگاهی به اطراف انداخت به شرکت مونتاژ شده.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097098.mp3"},{"sentence":"Some jokes are just not appropriate to tell in mixed company (= in a group of both men and women ) .","translation":"برخی از جوک ها برای گفتن در شرکت های مختلط (= در یک گروه زن و مرد) مناسب نیستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691306.mp3"},{"sentence":"Parents should teach their children how to behave in company.","translation":"والدین باید به فرزندان خود بیاموزند که چگونه در جمع رفتار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097102.mp3"}]'::jsonb,3),
