('69bdb96c-51fa-5b7c-b3be-8b776a94ca80','a27c8d1d-924d-5c5b-97d2-25e21bf19651',1,null,null,'spoken & written','to consider two or more things or people, in order to show how they are similar or different','[ transitive ]',null,'مقایسه کردن؛ سنجیدن؛ تشبیه کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The report compares the different types of home computer available.","translation":"این گزارش انواع مختلف کامپیوترهای خانگی موجود را مقایسه می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097153.mp3"},{"sentence":"The police compared the suspect’s fingerprints with those found at the crime scene.","translation":"پلیس اثر انگشت مظنون را با آثار کشف شده در صحنه جرم مقایسه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097156.mp3"},{"sentence":"Davies’ style of writing has been compared to Dickens’.","translation":"سبک نوشتن دیویس با دیکنز مقایسه شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691318.mp3"},{"sentence":"Compare and contrast the main characters of these two novels.","translation":"شخصیت های اصلی این دو رمان را با هم مقایسه و مقایسه کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691319.mp3"}]'::jsonb,4),
('e785a2f1-f75b-5d3a-9b17-c4fcb0ab9778','a27c8d1d-924d-5c5b-97d2-25e21bf19651',2,null,null,'spoken & written',null,null,'compared to/with something','مقایسه کردن؛ سنجیدن؛ تشبیه کردن','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ea46a007-13da-5a6a-9e5a-0e471f318c7d','a27c8d1d-924d-5c5b-97d2-25e21bf19651',3,null,null,'spoken & written','to be better or worse than something else','[ intransitive ]',null,'بهتر یا بدتر از چیز دیگری بودن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The quality of English wines can now compare with wines from Germany.","translation":"کیفیت شراب های انگلیسی اکنون می تواند با شراب های آلمان مقایسه شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691322.mp3"},{"sentence":"How does life in Britain compare with life in the States?","translation":"زندگی در بریتانیا چگونه با زندگی در ایالات متحده مقایسه می شود؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001097188.mp3"},{"sentence":"The imported fabric is 30% cheaper and compares favourably (= is as good ) in quality.","translation":"پارچه وارداتی 30 درصد ارزان تر است و از نظر کیفیت نسبتاً مطلوب (= به همان اندازه خوب است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691323.mp3"}]'::jsonb,3),
