('09d32266-22ee-5413-8929-6f6d909a8c92','a0f66e00-0677-5707-9a94-5ba5d094c5f7',1,'business','کسب و کار','spoken & written','if one company or country competes with another, it tries to get people to buy its goods or services rather than those available from another company or country',null,null,'رقابت کردن (شرکت، کشور)؛ هم‌پروردی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They found themselves competing with foreign companies for a share of the market.","translation":"آنها خود را در رقابت با شرکت های خارجی برای کسب سهمی از بازار دیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001098385.mp3"},{"sentence":"The Renault Clio competes against such cars as the Peugeot 206.","translation":"رنو کلیو با خودروهایی مانند پژو 206 رقابت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691404.mp3"},{"sentence":"The stores have to compete for customers in the Christmas season.","translation":"فروشگاه ها باید در فصل کریسمس برای مشتریان رقابت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691407.mp3"},{"sentence":"The company must be able to compete in the international marketplace.","translation":"شرکت باید بتواند در بازار بین المللی رقابت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691410.mp3"},{"sentence":"Several advertising agencies are competing to get the contract.","translation":"چندین آژانس تبلیغاتی برای گرفتن این قرارداد با هم رقابت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001098394.mp3"},{"sentence":"Small independent bookstores simply can’t compete with the big national chains.","translation":"کتابفروشی های مستقل کوچک به سادگی نمی توانند با زنجیره های بزرگ ملی رقابت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001098398.mp3"}]'::jsonb,6),
('f653711b-7eb1-5463-bb3b-6cae6cff1874','a0f66e00-0677-5707-9a94-5ba5d094c5f7',2,'person','شخص','spoken & written','to try to gain something and stop someone else from having it or having as much of it',null,null,'تلاش برای به دست آوردن چیزی و جلوگیری از داشتن آن یا داشتن مقدار زیادی از آن توسط شخص دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She and her sister are always competing for attention.","translation":"او و خواهرش همیشه برای جلب توجه در حال رقابت هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001098388.mp3"},{"sentence":"I had to compete against 19 other people for the job.","translation":"برای این کار باید با 19 نفر دیگر رقابت می کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691418.mp3"},{"sentence":"As a stepmother, don’t even try to compete with the children’s mother for their love.","translation":"به عنوان یک نامادری، حتی سعی نکنید با مادر بچه ها برای عشق آنها رقابت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691421.mp3"}]'::jsonb,3),
('25ffeb78-cbf0-502e-b287-26a0ae8973da','a0f66e00-0677-5707-9a94-5ba5d094c5f7',3,'in a competition','در یک مسابقه','spoken & written','to take part in a competition or sports event',null,null,'برای شرکت در یک مسابقه یا رویداد ورزشی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How many runners will be competing in the marathon?","translation":"چه تعداد دونده در ماراتن شرکت خواهند کرد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001098404.mp3"},{"sentence":"Professional athletes may now compete at the Olympics.","translation":"ورزشکاران حرفه ای اکنون ممکن است در المپیک شرکت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691425.mp3"},{"sentence":"He’ll be competing against the world’s best.","translation":"او با بهترین های جهان رقابت خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001691428.mp3"}]'::jsonb,3),
('8730d0a3-ea3e-549e-a499-deaceb676e68','a0f66e00-0677-5707-9a94-5ba5d094c5f7',4,null,null,'spoken & written',null,null,'somebody/something can’t compete with somebody/something','رقابت کردن (شرکت، کشور)؛ هم‌پروردی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a897a2b9-c80f-5e39-acc2-f9d81f881ef4','36acdee8-9976-5d69-a540-69959333e722',1,null,null,'spoken & written','consisting of many different parts and often difficult to understand',null,null,'مختلط، پیچیده؛ ساختار پیچیده',array['complicated']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a complex system of highways","translation":"سیستم پیچیده ای از بزرگراه ها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001099793.mp3"},{"sentence":"Photosynthesis is a highly complex process.","translation":"فتوسنتز یک فرآیند بسیار پیچیده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001099794.mp3"},{"sentence":"Peter seemed to have an instant understanding of the most complex issues.","translation":"به نظر می‌رسید که پیتر درکی فوری از پیچیده‌ترین مسائل داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001697200.mp3"},{"sentence":"It was a very complex relationship between two complex people.","translation":"این یک رابطه بسیار پیچیده بین دو فرد پیچیده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001697201.mp3"}]'::jsonb,4),
('88b76fca-f53a-56e5-9f32-58b17b359a18','36acdee8-9976-5d69-a540-69959333e722',2,null,null,'technical','a complex word or sentence contains a main part and one or more other parts',null,null,'یک کلمه یا جمله پیچیده شامل یک بخش اصلی و یک یا چند بخش دیگر است','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('83f48607-f294-5d99-94f9-dcbd2ea1837e','f218541c-6fc0-584f-b1d3-7f405acfd5d1',1,null,null,'spoken & written','a group of buildings , or a large building with many parts, used for a particular purpose',null,null,'گروهی از ساختمان‌ها یا یک ساختمان بزرگ با قسمت‌های زیاد که برای هدف خاصی استفاده می‌شوند','{}'::text[],'{}'::text[],array['a leisure complex (= where you can play sports or relax ) The new leisure complex includes a swimming pool, a sauna and a gym.','a shopping complex Some old buildings were pulled down to make space for a new shopping complex.','a sports complex The sports complex also has six tennis courts.','an entertainment complex (= with cinemas, restaurants and other places to go ) There are plans for an entertainment complex with cinemas and a bowling alley.','a holiday complex (= one where people go for holidays ) The lively holiday complex has plenty of nightclubs, bars, and restaurants.','a housing/residential complex (= for people to live in ) Architects designed the residential complexes near the beach.','a retail/commercial complex (= for shops, businesses, or industries ) a ten-screen movie theater and retail complex','an office/museum/hospital etc complex a 120-acre office complex near Las Vegas','an apartment complex American English a luxury apartment complex on Fulton Street']::text[],'[{"sentence":"The town has one of the best leisure complexes in the country.","translation":"این شهر دارای یکی از بهترین مجتمع های تفریحی کشور است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000876222.mp3"},{"sentence":"a three-story apartment complex","translation":"یک مجتمع آپارتمانی سه طبقه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001697014.mp3"}]'::jsonb,2),
('45473c50-eb75-5c1a-aa25-1e7e995188f4','f218541c-6fc0-584f-b1d3-7f405acfd5d1',2,null,null,'spoken & written',null,null,'a complex of something',null,'{}'::text[],'{}'::text[],array['a leisure complex (= where you can play sports or relax ) The new leisure complex includes a swimming pool, a sauna and a gym.','a shopping complex Some old buildings were pulled down to make space for a new shopping complex.','a sports complex The sports complex also has six tennis courts.','an entertainment complex (= with cinemas, restaurants and other places to go ) There are plans for an entertainment complex with cinemas and a bowling alley.','a holiday complex (= one where people go for holidays ) The lively holiday complex has plenty of nightclubs, bars, and restaurants.','a housing/residential complex (= for people to live in ) Architects designed the residential complexes near the beach.','a retail/commercial complex (= for shops, businesses, or industries ) a ten-screen movie theater and retail complex','an office/museum/hospital etc complex a 120-acre office complex near Las Vegas','an apartment complex American English a luxury apartment complex on Fulton Street']::text[],'[]'::jsonb,0),
('ecfaba14-7abe-5be5-a347-20968661efa0','f218541c-6fc0-584f-b1d3-7f405acfd5d1',3,null,null,'spoken & written','an emotional problem in which someone is unnecessarily anxious about something or thinks too much about something',null,null,'یک مشکل عاطفی که در آن شخصی به طور غیر ضروری در مورد چیزی مضطرب است یا بیش از حد در مورد چیزی فکر می کند','{}'::text[],'{}'::text[],array['a leisure complex (= where you can play sports or relax ) The new leisure complex includes a swimming pool, a sauna and a gym.','a shopping complex Some old buildings were pulled down to make space for a new shopping complex.','a sports complex The sports complex also has six tennis courts.','an entertainment complex (= with cinemas, restaurants and other places to go ) There are plans for an entertainment complex with cinemas and a bowling alley.','a holiday complex (= one where people go for holidays ) The lively holiday complex has plenty of nightclubs, bars, and restaurants.','a housing/residential complex (= for people to live in ) Architects designed the residential complexes near the beach.','a retail/commercial complex (= for shops, businesses, or industries ) a ten-screen movie theater and retail complex','an office/museum/hospital etc complex a 120-acre office complex near Las Vegas','an apartment complex American English a luxury apartment complex on Fulton Street']::text[],'[{"sentence":"I used to have a complex about my looks.","translation":"من قبلاً در مورد ظاهرم عقده داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001697017.mp3"}]'::jsonb,1),
('a2a61645-4d7a-5d48-99c6-49016a0771e3','76b9b2f7-e586-511f-8455-bc7c52d72413',1,null,null,'spoken & written','an idea of how something is, or how something should be done',null,null,'مفهوم، تصور ذهنی؛ ایده','{}'::text[],'{}'::text[],array['a new concept Part of a teacher’s job is to introduce new concepts to students.','a basic/fundamental concept The children are taught the basic concepts of mathematics.','a key/central/important concept The title tells you something about the central concept of the poem.','a difficult concept Difficult concepts can sometimes be explained by diagrams or graphs.','a simple concept Cause and effect is a fairly simple concept.','the whole concept of something Some people reject the whole concept of evolution.','a general/broad concept The book begins with some general historical concepts.','an abstract concept (= based on general ideas rather than on something that exists ) He finds it hard to grasp abstract concepts.','a theoretical concept (= that exists only as a theory ) The theoretical concepts of psychology, for example Freud’s ideas, are also useful in the study of literature.','a legal/mathematical/marketing etc concept Democracy is a very important political concept.','an alien concept (= an idea that is very strange or that does not exist ) In many countries, queuing for a bus is an alien concept.','an ambiguous/vague concept (= one that is not clear or is hard to define ) Creativity is an ambiguous concept.','have a concept of something Animals have no concept of their own mortality.','understand a concept The class will help you understand the basic concepts of physics.','grasp a concept (= understand it ) Children often grasp new concepts more quickly than adults.','introduce a concept The first year of the course introduces the basic concepts of management.','develop a concept The Greeks developed the concept of a scientific theory.']::text[],'[{"sentence":"the concept of total patient care","translation":"مفهوم مراقبت کامل از بیمار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000850803.mp3"},{"sentence":"the concept of infinite space","translation":"مفهوم فضای بی نهایت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687785.mp3"},{"sentence":"the concept that we are citizens of one world","translation":"این مفهوم که ما شهروندان یک جهان هستیم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687788.mp3"},{"sentence":"a new concept in business travel","translation":"مفهومی جدید در سفرهای کاری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000850800.mp3"},{"sentence":"our basic concepts of decent human behaviour","translation":"مفاهیم اساسی ما از رفتار شایسته انسانی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687792.mp3"},{"sentence":"It’s very simple, once you grasp the concept .","translation":"خیلی ساده است، وقتی مفهوم را درک کردید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687796.mp3"}]'::jsonb,6),
('a7527c73-2840-56a0-8080-a385a07b96ec','5de07441-3488-5be5-87c3-fd798c8d5fc3',1,'worry','نگرانی','spoken & written','a feeling of worry about something important','[ uncountable ]',null,'نگرانی، دغدغه؛ علاقه (به)؛ شرکت','{}'::text[],'{}'::text[],array['cause concern The announcement will cause concern in the Middle East.','feel concern A lot of people felt some concern about the proposal.','express concern Police officials expressed concern about robberies, which have increased by 23%.','voice concern formal (= express concern ) Some people have voiced concern about the state of the president''s health.','raise concerns formal: The incident has raised concerns over safety at the power station.','be of concern Of course, this is of great concern to parents.','be a cause for concern Rising global temperatures are a cause for serious concern.','be a matter of concern Elderly people in particular feel that crime is a matter of concern for them.','amid concern that/over something (= because there is concern about something ) Shares fell slightly amid concern that the economy is slowing.','great/serious/considerable concern The spread of the disease is an issue of considerable concern.','grave concern (= very great concern ) This disagreement was a matter of grave concern to the US.','a real/genuine concern Pensions are a genuine concern to many people.','a particular concern Noise is a particular concern of those living near the airport.','growing/mounting concern Growing concern has been expressed over the pollution of the North Sea.','a common concern (= one that many people share ) Rising food prices are a common concern.','public concern (= felt by the public ) Public concern about the destruction of the rain forests could harm the timber business.','national concern The lack of good cheap public transport is a matter of national concern.','widespread concern There seems to be widespread concern about the state of our hospitals.']::text[],'[{"sentence":"The recent rise in crime is a matter of considerable public concern.","translation":"افزایش اخیر جرم و جنایت موضوعی است که باعث نگرانی عمومی قابل توجهی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100254.mp3"},{"sentence":"our concern for human rights","translation":"نگرانی ما برای حقوق بشر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100260.mp3"},{"sentence":"the rise of concern about the environment","translation":"افزایش نگرانی در مورد محیط زیست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100257.mp3"},{"sentence":"the growing concern over inflation","translation":"نگرانی فزاینده در مورد تورم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687948.mp3"},{"sentence":"concern with worsening law and order","translation":"نگرانی از بدتر شدن نظم و قانون","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687949.mp3"},{"sentence":"increased concern that the war could continue for a long time","translation":"افزایش نگرانی از ادامه جنگ برای مدت طولانی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687952.mp3"},{"sentence":"The activities of the far right have been a cause for concern for a while now.","translation":"فعالیت های راست افراطی مدتی است که باعث نگرانی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687953.mp3"},{"sentence":"In her last days the poet expressed concern for her father.","translation":"شاعر در آخرین روزهای زندگی خود نسبت به پدرش ابراز نگرانی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687954.mp3"},{"sentence":"One of the concerns that people have is the side effects of treatment.","translation":"یکی از نگرانی هایی که مردم دارند عوارض درمان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100249.mp3"},{"sentence":"Education remains the electorate’s main concern.","translation":"آموزش همچنان دغدغه اصلی رای دهندگان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687958.mp3"},{"sentence":"the concerns expressed by parents","translation":"نگرانی های ابراز شده توسط والدین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687959.mp3"}]'::jsonb,11),
('15d2c448-cc39-513f-b02a-f54f609f8c42','5de07441-3488-5be5-87c3-fd798c8d5fc3',2,'something important','چیزی مهم','spoken & written','something that is important to you or that involves you','[ countable, uncountable ]',null,'چیزی که برای شما مهم است یا شما را درگیر می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His main concern is to be able to provide for his family.","translation":"دغدغه اصلی او این است که بتواند مخارج خانواده اش را تامین کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100273.mp3"},{"sentence":"The consumer has become a major concern for this government.","translation":"مصرف کننده به دغدغه اصلی این دولت تبدیل شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687966.mp3"},{"sentence":"topics of concern to television viewers","translation":"موضوعات مورد توجه بینندگان تلویزیون","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687967.mp3"}]'::jsonb,3),
('4bfc87db-0b90-5891-b08f-79e9135c69b7','5de07441-3488-5be5-87c3-fd798c8d5fc3',3,'feeling for somebody','احساس برای کسی','spoken & written','a feeling of wanting someone to be happy and healthy','[ singular, uncountable ]',null,'احساس اینکه می خواهید کسی شاد و سالم باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was moved by her obvious concern.","translation":"او از نگرانی آشکار او متاثر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687972.mp3"},{"sentence":"parents’ loving concern for their children","translation":"توجه محبت آمیز والدین به فرزندانشان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100282.mp3"}]'::jsonb,2),
