('8d0e7dbf-7e9c-5e70-aa6a-9b1a7adaa55a','5de07441-3488-5be5-87c3-fd798c8d5fc3',6,'business','کسب و کار','spoken & written','a business or company','[ countable ]',null,'یک کسب و کار یا شرکت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The restaurant is a family concern.","translation":"رستوران یک دغدغه خانوادگی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100299.mp3"},{"sentence":"We will continue to run the company as a going concern (= a business that is financially successful ) .","translation":"ما به اداره شرکت به عنوان یک شرکت ادامه خواهیم داد (= کسب و کاری که از نظر مالی موفق است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687974.mp3"}]'::jsonb,2),
('9d5e9c2e-3800-5339-817a-c621fc3df4ce','8dd0cdfb-9f24-59a2-b6f7-cf7909f1ad32',1,null,null,'spoken & written','if a story , book, report etc concerns someone or something, it is about them','[ not in passive ]',null,'مربوط بودن، درباره بودن؛ نگران بودن؛ دل‌مشغولی داشتن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This study concerns couples’ expectations of marriage.","translation":"این مطالعه به انتظارات زوجین از ازدواج می پردازد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000850889.mp3"},{"sentence":"The report concerns the drug traffic on the Mexican–US border.","translation":"این گزارش مربوط به قاچاق مواد مخدر در مرز مکزیک و ایالات متحده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687815.mp3"},{"sentence":"The book is about women’s experiences of war.","translation":"کتاب درباره تجربیات زنان از جنگ است.","audio_url":null}]'::jsonb,3),
('04bafb2d-b397-5eb9-a5ef-7e470bcc2834','8dd0cdfb-9f24-59a2-b6f7-cf7909f1ad32',2,null,null,'spoken & written','to make someone feel worried or upset',null,null,'ایجاد احساس نگرانی یا ناراحتی در کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Issues like food additives do concern me.","translation":"مسائلی مانند افزودنی های غذایی برای من نگران کننده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000850884.mp3"}]'::jsonb,1),
('0e664ea8-87f3-5a00-bfc9-e3a4539f69f1','8dd0cdfb-9f24-59a2-b6f7-cf7909f1ad32',3,null,null,'spoken & written','if an activity, situation, rule etc concerns you, it affects you or involves you',null,null,'اگر یک فعالیت، موقعیت، قانون و غیره به شما مربوط می شود، بر شما تأثیر می گذارد یا شما را درگیر می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The tax changes will concern large corporations rather than small businesses.","translation":"تغییرات مالیاتی به جای شرکت های کوچک مربوط به شرکت های بزرگ خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000850879.mp3"}]'::jsonb,1),
