('f2c5a14a-b509-537b-aec8-81f7bae13579','f6da225f-1116-52d3-91c2-46bf2c1ed2d7',1,'state officially','به صورت رسمی اعلام شود','spoken & written','to state officially and publicly that a particular situation exists or that something is true','[ transitive ]',null,'اعلام کردن، رسماً بیان کردن؛ اعلام جرم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A state of emergency has been declared.","translation":"وضعیت فوق العاده اعلام شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706517.mp3"},{"sentence":"The court declared that Brown’s case should be reviewed.","translation":"دادگاه اعلام کرد که پرونده براون باید بررسی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706520.mp3"},{"sentence":"Several countries wanted Antarctica to be declared a ‘world park’.","translation":"چندین کشور خواستار آن بودند که قطب جنوب به عنوان «پارک جهانی» معرفی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002084292.mp3"},{"sentence":"The city was declared to be in a state of siege.","translation":"شهر در حالت محاصره اعلام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706523.mp3"},{"sentence":"I declare you man and wife.","translation":"من شما را مرد و زن اعلام می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706524.mp3"},{"sentence":"The war was declared illegal by the International Court of Justice.","translation":"این جنگ توسط دیوان بین المللی دادگستری غیرقانونی اعلام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706527.mp3"},{"sentence":"Mr Steel has been declared bankrupt (= it has been officially stated that he cannot pay his debts ) .","translation":"آقای فولاد ورشکست شد (= رسماً اعلام شد که نمی تواند بدهی خود را پرداخت کند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706528.mp3"},{"sentence":"We celebrate September 16, the day when Mexico declared independence from Spain (= officially stated that it was no longer ruled by Spain ) .","translation":"ما 16 سپتامبر را جشن می گیریم، روزی که مکزیک استقلال خود را از اسپانیا اعلام کرد (= رسما اعلام کرد که دیگر توسط اسپانیا اداره نمی شود).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706533.mp3"}]'::jsonb,8),
('c039e667-8329-5b3c-858d-0c3b548d5fa3','f6da225f-1116-52d3-91c2-46bf2c1ed2d7',2,'state what you think','آنچه را که فکر می کنید بیان کنید','spoken & written','to say publicly what you think or feel','[ transitive ]',null,'به طور عمومی آنچه را که فکر می کنید یا احساس می کنید بگویید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘It’s not fair, ’ Jane declared.","translation":"جین گفت: «عادلانه نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706540.mp3"},{"sentence":"He declared his intention to stand for president.","translation":"او اعلام کرد که قصد دارد نامزد ریاست جمهوری شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706541.mp3"},{"sentence":"Carol held a press conference and declared that she was innocent.","translation":"کارول یک کنفرانس مطبوعاتی برگزار کرد و اعلام کرد که بی گناه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706549.mp3"},{"sentence":"Edward declared himself angry and frustrated.","translation":"ادوارد خود را عصبانی و ناامید اعلام کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706552.mp3"}]'::jsonb,4),
