('1a09bfa3-51a7-5bf1-bf9b-4ef735aef5ba','f6da225f-1116-52d3-91c2-46bf2c1ed2d7',4,'money/property etc','پول / دارایی و غیره','spoken & written','to state on an official government form how much money you have earned , what property you own etc','[ transitive ]',null,'در یک فرم رسمی دولتی بیان کنید که چقدر پول به دست آورده اید، چه دارایی دارید و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"All tips are counted as part of your earnings and must be declared.","translation":"همه نکات به عنوان بخشی از درآمد شما محاسبه می شود و باید اعلام شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001131697.mp3"}]'::jsonb,1),
