('0d71fa3a-6b02-519a-863a-f7b1a9536611','3d167e75-a661-5458-8a63-dfc31f096329',1,null,null,'spoken & written','a decrease in the quality , quantity , or importance of something',null,null,'کاهش، افت (کیفیت، مقدار، اهمیت)؛ رد مؤدبانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There has been a decline in the size of families.","translation":"تعداد خانواده ها کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000837039.mp3"},{"sentence":"the decline of manufacturing","translation":"کاهش تولید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706319.mp3"},{"sentence":"a rapid decline in unemployment","translation":"کاهش سریع بیکاری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000837042.mp3"},{"sentence":"The island’s population initially numbered 180, but there was a gradual decline until only 40 people were left.","translation":"جمعیت جزیره در ابتدا 180 نفر بود، اما به تدریج کاهش یافت تا اینکه تنها 40 نفر باقی ماندند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706322.mp3"},{"sentence":"the economic decline faced by many cities","translation":"کاهش اقتصادی که بسیاری از شهرها با آن روبرو هستند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830222.mp3"},{"sentence":"the widely held belief that educational standards are in decline","translation":"باور عمومی مبنی بر اینکه استانداردهای آموزشی رو به افول است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000444.mp3"},{"sentence":"The port fell into decline in the 1950s.","translation":"این بندر در دهه 1950 رو به افول گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000837046.mp3"}]'::jsonb,7),
('4e9360f4-21f4-59fa-ba98-06cebdc4c88e','7158a6bc-6023-5ef9-b10d-b8b5fb2cf87e',1,'decrease','کاهش یابد','spoken & written','to decrease in quantity or importance','[ intransitive ]',null,'کاهش یافتن، افت کردن؛ رد کردن مؤدبانه (دعوت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Spending on information technology has declined.","translation":"هزینه های مربوط به فناوری اطلاعات کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132302.mp3"},{"sentence":"Car sales have declined by a quarter.","translation":"فروش خودرو یک چهارم کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132303.mp3"},{"sentence":"After the war, the city declined in importance.","translation":"پس از جنگ از اهمیت شهر کاسته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706571.mp3"}]'::jsonb,3),
('f76912b1-a220-5b9f-9cb9-91887998350f','7158a6bc-6023-5ef9-b10d-b8b5fb2cf87e',2,'say no','بگو نه','formal','to say no politely when someone invites you somewhere, offers you something, or wants you to do something','[ intransitive, transitive ]',null,'وقتی کسی شما را به جایی دعوت می کند، چیزی به شما پیشنهاد می دهد یا از شما می خواهد کاری انجام دهید، مؤدبانه نه بگویید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Offered the position of chairman, Smith declined, preferring to keep his current job.","translation":"اسمیت با پیشنهاد سمت رئیس، نپذیرفت و ترجیح داد شغل فعلی خود را حفظ کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132318.mp3"},{"sentence":"Mary declined a hot drink and went to her room.","translation":"مریم نوشیدنی گرم را رد کرد و به اتاقش رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706573.mp3"},{"sentence":"Mary declined Jay’s invitation to dinner.","translation":"مری دعوت جی برای شام را رد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132321.mp3"},{"sentence":"The court declined to review her case.","translation":"دادگاه از بررسی پرونده او خودداری کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706576.mp3"},{"sentence":"The minister declined to comment (= refused to speak to people who report the news ) about the progress of the peace talks.","translation":"وزیر از اظهار نظر (= از صحبت با افرادی که اخبار را گزارش می کنند خودداری کرد) در مورد پیشرفت مذاکرات صلح.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706577.mp3"}]'::jsonb,5),
('0f66b9bb-9358-5c4d-a66c-0c4122ea610f','7158a6bc-6023-5ef9-b10d-b8b5fb2cf87e',3,'become worse','بدتر شدن','spoken & written','to become gradually worse in quality','[ intransitive ]',null,'به تدریج از نظر کیفیت بدتر شود',array['deteriorate']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her health has been declining progressively for several months.","translation":"سلامتی او چند ماه است که به تدریج رو به کاهش بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132310.mp3"},{"sentence":"Qualified staff are leaving and standards are declining.","translation":"کارکنان واجد شرایط می روند و استانداردها رو به کاهش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706583.mp3"}]'::jsonb,2),
('473197db-61f2-501c-b6ed-46b56b47bf50','7158a6bc-6023-5ef9-b10d-b8b5fb2cf87e',4,null,null,'spoken & written',null,null,'somebody’s declining years','کاهش یافتن، افت کردن؛ رد کردن مؤدبانه (دعوت)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9ccc249f-b697-5917-b7c5-89efc24f5944','7158a6bc-6023-5ef9-b10d-b8b5fb2cf87e',5,'grammar','دستور زبان','spoken & written','if a noun , pronoun , or adjective declines, its form changes according to whether it is the subject , object etc of a sentence','[ intransitive ]',null,'اگر یک اسم، ضمیر یا صفت کاهش یابد، شکل آن بسته به اینکه فاعل، مفعول و غیره یک جمله باشد تغییر می کند.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ca2d2f54-be8f-57d4-8a41-838105f1ddf3','9f65aea7-5f98-535d-a97f-5e53519f1709',1,'protection','حفاظت','spoken & written','the act of protecting something or someone from attack','[ uncountable ]','self-defence','دفاع، پدافند؛ دفاعیات؛ پشتوانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In Britain, the defence of the country has historically been left to the navy.","translation":"در بریتانیا دفاع از کشور در طول تاریخ به نیروی دریایی واگذار شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830264.mp3"},{"sentence":"a firm commitment to the defense of human rights","translation":"تعهد محکم به دفاع از حقوق بشر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830265.mp3"},{"sentence":"The first line of defence is a smoke detector.","translation":"اولین خط دفاعی آشکارساز دود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706752.mp3"},{"sentence":"The area’s flood defences need repair.","translation":"سیلاب منطقه نیاز به تعمیر دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706763.mp3"},{"sentence":"The immune system is the body’s defence against infection.","translation":"سیستم ایمنی دفاع بدن در برابر عفونت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706766.mp3"}]'::jsonb,5),
('323aa5d2-930e-596a-b26c-8f14453535cd','9f65aea7-5f98-535d-a97f-5e53519f1709',2,'military','نظامی','spoken & written','all the systems, people, materials etc that a country uses to protect itself from attack','[ uncountable ]',null,'تمام سیستم ها، افراد، مواد و غیره که یک کشور برای محافظت از خود در برابر حمله استفاده می کند','{}'::text[],'{}'::text[],array['a defence force (= group of soldiers, pilots etc trained to defend a country ) The country''s defence forces are on standby in case of an attack.','a defence system (= a system of people, organizations etc to defend a country ) Is the national defence system adequate?','a defence policy Ministers in Brussels have been discussing a possible European defence policy.','defence spending/expenditure There were plans to cut defence spending by one billion pounds.','the defence budget (= amount of money a government makes available for defence ) They have called for the defence budget to be increased.','the Defence Department (= part of the government dealing with defence ) This is secret information, known only to the Defence Department.','the Defence Secretary (= person in a government in charge of defence ) The Defence Secretary is under pressure to resign.']::text[],'[{"sentence":"calls for a national debate on defence","translation":"خواستار یک بحث ملی در مورد دفاع است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830266.mp3"},{"sentence":"the Defense Department","translation":"وزارت دفاع","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001132989.mp3"},{"sentence":"The invading army easily overcame the town’s defences.","translation":"ارتش متجاوز به راحتی بر دفاعیات شهر غلبه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706777.mp3"}]'::jsonb,3),
('62772288-9fa7-5273-a656-9ff0c579b33d','9f65aea7-5f98-535d-a97f-5e53519f1709',3,'against criticism','در برابر انتقاد','spoken & written','something that you say or do in order to support someone or something that is being criticized','[ countable, uncountable ]',null,'چیزی که به منظور حمایت از کسی یا چیزی که مورد انتقاد قرار می گیرد، می گویید یا انجام می دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jean wrote a letter to the paper in Angela’s defense.","translation":"ژان در دفاع از آنجلا نامه ای به روزنامه نوشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706781.mp3"},{"sentence":"a philosophical defence of nationalism","translation":"دفاع فلسفی از ناسیونالیسم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706784.mp3"},{"sentence":"Evelyn Waugh came to Wilson’s defence and acknowledged the brilliance of the book’s themes.","translation":"ایولین وو به دفاع از ویلسون آمد و درخشندگی مضامین کتاب را تصدیق کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830269.mp3"}]'::jsonb,3),
('cc5838d5-e8b7-5b63-9855-62a63876a48c','9f65aea7-5f98-535d-a97f-5e53519f1709',4,'in a law court','در دادگاه حقوقی','spoken & written','the things that are said in a court of law to prove that someone is not guilty of a crime','[ countable ]','prosecution','مواردی که در دادگاه برای اثبات بی گناهی کسی گفته می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Major has a good defence and believes he will win the case.","translation":"میجر دفاع خوبی دارد و معتقد است در این پرونده پیروز خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133019.mp3"},{"sentence":"a defence lawyer","translation":"یک وکیل مدافع","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706786.mp3"},{"sentence":"The defense called only one witness.","translation":"دفاع فقط یک شاهد را فراخواند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133024.mp3"}]'::jsonb,3),
('8203ff4d-9de3-55f1-8c15-64ef95d00a21','9f65aea7-5f98-535d-a97f-5e53519f1709',5,'emotions','احساسات','spoken & written','something you do or a way of behaving that prevents you from seeming weak or being hurt by others','[ countable ]',null,'کاری که انجام می دهید یا روشی از رفتار که مانع از ضعیف به نظر رسیدن یا آسیب دیدن شما توسط دیگران می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Liz dropped her defences and began to relax.","translation":"لیز دفاع خود را رها کرد و شروع به آرامش کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001706788.mp3"}]'::jsonb,1),
('467c9d58-0df6-5a87-85cf-5ef140d2fb4b','9f65aea7-5f98-535d-a97f-5e53519f1709',6,'sport','ورزش','spoken & written','the players on a sports team whose main job is to try to prevent the other team from getting points','[ countable ]',null,'بازیکنان یک تیم ورزشی که وظیفه اصلی آنها تلاش برای جلوگیری از امتیاز گرفتن تیم دیگر است','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('05227e0c-afae-5611-b1ad-9484ec8fac89','5362ac3c-5e83-5809-ac51-c6a0979e08bd',1,'take something somewhere','چیزی را به جایی ببر','spoken & written','to take goods, letters , packages etc to a particular place or person','[ intransitive, transitive ]',null,'تحویل دادن؛ رساندن (نطق، حمله)؛ نجات دادن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The morning mail has just been delivered.","translation":"پست صبح به تازگی تحویل داده شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133451.mp3"},{"sentence":"Do you deliver on Saturdays?","translation":"شنبه ها تحویل میگیرید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684493.mp3"},{"sentence":"They set off to deliver supplies to an isolated village.","translation":"آنها به راه افتادند تا آذوقه را به روستایی دورافتاده برسانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133454.mp3"},{"sentence":"I’m having some flowers delivered for her birthday.","translation":"من برای تولدش چند گل تحویل می دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684496.mp3"}]'::jsonb,4),
