('6e0e4671-4c91-515f-8803-0cd49a7103e3','5362ac3c-5e83-5809-ac51-c6a0979e08bd',3,'do something you should do','کاری را که باید انجام دهید انجام دهید','spoken & written','to do or provide the things you are expected to, because you are responsible for them or they are part of your job','[ intransitive, transitive ]',null,'کارهایی را که از شما انتظار می رود انجام دهید یا ارائه دهید، زیرا شما مسئول آنها هستید یا بخشی از کار شما هستند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the costs of delivering adequate nursing care","translation":"هزینه های ارائه مراقبت های پرستاری کافی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133470.mp3"},{"sentence":"the failure of some services to deliver the goods (= do what they have promised )","translation":"عدم موفقیت برخی از خدمات در تحویل کالا (= انجام آنچه وعده داده اند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684503.mp3"},{"sentence":"The company will deliver on its promises .","translation":"این شرکت به وعده های خود عمل خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684507.mp3"}]'::jsonb,3),
('ec3893e2-ac54-5fdc-ad3c-f30c1d9de13a','5362ac3c-5e83-5809-ac51-c6a0979e08bd',4,'baby','عزیزم','spoken & written','to help a woman give birth to her baby , or to give birth to a baby','[ transitive ]',null,'برای کمک به زنی که بچه اش را به دنیا بیاورد یا بچه ای به دنیا بیاورد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They rushed her to hospital where doctors delivered her baby.","translation":"آنها او را سریع به بیمارستان بردند و پزشکان نوزادش را به دنیا آوردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133484.mp3"}]'::jsonb,1),
('7a514c2a-cbeb-5941-899d-5b244d60628c','5362ac3c-5e83-5809-ac51-c6a0979e08bd',5,'blow/shock etc','ضربه / شوک و غیره','spoken & written','to give something such as a blow , shock , or warning to someone or something','[ transitive ]',null,'دادن چیزی مانند ضربه، شوک، یا هشدار به کسی یا چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He delivered a strong warning about the dangers facing the government.","translation":"او در مورد خطرات پیش روی دولت هشدار جدی داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133492.mp3"}]'::jsonb,1),
