('da979a4b-7fa1-5346-b38d-30c70074f601','5362ac3c-5e83-5809-ac51-c6a0979e08bd',7,'person','شخص','formal','to put someone into someone else’s control','[ transitive ]',null,'قرار دادن کسی در کنترل شخص دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sharett had betrayed him and delivered him to the enemy.","translation":"شرت به او خیانت کرده بود و او را به دست دشمن سپرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133506.mp3"}]'::jsonb,1),
('81511f9e-24b9-53fa-b08e-20f9cc311b5a','5362ac3c-5e83-5809-ac51-c6a0979e08bd',8,'votes','رای','spoken & written','to get the votes or support of a particular group of people in an election','[ transitive ]',null,'برای به دست آوردن رای یا حمایت گروه خاصی از مردم در یک انتخابات','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He cannot deliver the Latino vote.","translation":"او نمی تواند رای لاتین را ارائه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001133514.mp3"}]'::jsonb,1),
('182ce450-cd7d-564d-9f24-8c3f7eb544b5','5362ac3c-5e83-5809-ac51-c6a0979e08bd',9,'make somebody free of something','کسی را از چیزی رها کن','literary','to help someone escape from something bad or evil','[ transitive ]',null,'برای کمک به کسی که از چیزی بد یا بد فرار کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Deliver us from evil, ’ she prayed.","translation":"او دعا کرد: «ما را از شر رهایی بخش».","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684530.mp3"}]'::jsonb,1),
('269bd46a-a3b7-508a-8789-50da73ac788d','fa2986b2-fc77-5eed-bb67-58d81e4a0932',1,null,null,'spoken & written','someone whose job is to treat people’s teeth',null,null,'دندان‌پزشک','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m going to the dentist this afternoon.","translation":"امروز بعدازظهر می روم دندانپزشک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747934.mp3"}]'::jsonb,1),
('933f5d27-f68d-58c4-b32f-2212cfc18492','bd7f741f-495f-50d7-902f-0823a363b8eb',1,null,null,'spoken & written','a part of the cost of something you are buying that you pay some time before you pay the rest of it',null,null,'بیعانه، ودیعه؛ رسوب؛ سپرده (پول)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A deposit of 10% is required.","translation":"سپرده 10% الزامی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755669.mp3"},{"sentence":"We put down a deposit on a house.","translation":"ودیعه گذاشتیم روی یک خانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136191.mp3"}]'::jsonb,2),
('fe751e90-8348-5b4f-b982-ebf3bef8d2d7','bd7f741f-495f-50d7-902f-0823a363b8eb',2,null,null,'spoken & written','money that you pay when you rent something such as an apartment or car, which will be given back if you do not damage it',null,null,'پولی که هنگام اجاره چیزی مانند آپارتمان یا ماشین می پردازید و در صورت عدم آسیب رساندن به آن پس داده می شود','{}'::text[],'{}'::text[],array['pay a deposit Car hire firms may ask you to pay a deposit in advance.','get your deposit back You''ll get your deposit back when all the bills have been paid.','lose your deposit (= not get it back ) If there is any damage to the apartment, you may lose your deposit.','give somebody their deposit back When I left, the landlord refused to give me my deposit back.','return somebody''s deposit formal (= give it back to them ) Your deposit will be returned to you when you leave the flat.','refundable/returnable (= that you get back later if there is no damage ) We ask for a refundable deposit of 500 Euros.']::text[],'[{"sentence":"We ask for one month’s rent in advance, plus a deposit of $500.","translation":"ما از قبل اجاره یک ماهه به اضافه 500 دلار ودیعه درخواست می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755672.mp3"}]'::jsonb,1),
('421efda1-b4b0-5d45-b1da-15a810bd0400','bd7f741f-495f-50d7-902f-0823a363b8eb',3,null,null,'spoken & written','an amount of money that is paid into a bank account',null,null,'مقدار پولی که به حساب بانکی واریز می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’d like to make a deposit (= pay some money ) into my savings account.","translation":"من می خواهم یک واریز (= مقداری پول) به حساب پس انداز خود واریز کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755675.mp3"}]'::jsonb,1),
('b889316c-c294-535d-83bd-3f21dda26b66','bd7f741f-495f-50d7-902f-0823a363b8eb',4,null,null,'spoken & written','a layer of a mineral , metal etc that is left in soil or rocks through a natural process',null,null,'لایه ای از یک ماده معدنی، فلز و غیره که طی یک فرآیند طبیعی در خاک یا سنگ ها باقی می ماند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"rich deposits of gold in the hills","translation":"ذخایر غنی طلا در تپه ها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755682.mp3"}]'::jsonb,1),
('9c762c85-7c33-57d0-9b37-19ac0db74d48','bd7f741f-495f-50d7-902f-0823a363b8eb',5,null,null,'spoken & written','an amount or layer of a substance that gradually develops in a particular place',null,null,'مقدار یا لایه ای از یک ماده که به تدریج در یک مکان خاص ایجاد می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"fatty deposits on the heart","translation":"رسوبات چربی روی قلب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136223.mp3"}]'::jsonb,1),
('dae83918-9249-5f58-8164-99bec3a51019','bd7f741f-495f-50d7-902f-0823a363b8eb',6,null,null,'spoken & written','an amount of money paid by a candidate in a political election in Britain, that is returned to them if they get enough votes',null,null,'مبلغی که یک نامزد در یک انتخابات سیاسی در بریتانیا پرداخت کرده و در صورت کسب آرای کافی به آنها بازگردانده می شود.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('54e284c7-97e4-51eb-83cf-c236a93b9a2e','f6ace92b-adb9-5f2a-97f1-f90a06a92070',1,null,null,'formal','to put something down in a particular place','[ transitive always + adverb/preposition ]',null,'گذاشتن چیزی در مکانی خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The female deposits her eggs directly into the water.","translation":"ماده تخم های خود را مستقیماً در آب قرار می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136250.mp3"}]'::jsonb,1),
('bd50efe9-cb18-589b-8227-40f279a9f851','f6ace92b-adb9-5f2a-97f1-f90a06a92070',2,null,null,'spoken & written','to leave a layer of a substance on the surface of something, especially gradually','[ transitive ]',null,'گذاشتن لایه ای از ماده روی سطح چیزی، به خصوص به تدریج','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"As the river slows down, it deposits a layer of soil.","translation":"با کاهش سرعت رودخانه، لایه ای از خاک رسوب می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136255.mp3"}]'::jsonb,1),
('0c3831b9-7fe1-5145-af35-ba908edb15f4','f6ace92b-adb9-5f2a-97f1-f90a06a92070',3,null,null,'spoken & written','to put money or something valuable in a bank or other place where it will be safe','[ transitive ]',null,'قرار دادن پول یا چیزی با ارزش در بانک یا مکان دیگری که در آن امن باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You are advised to deposit your valuables in the hotel safe.","translation":"به شما توصیه می شود اشیای قیمتی خود را در صندوق امانات هتل بسپارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755687.mp3"},{"sentence":"The dollars are then deposited with banks outside the USA.","translation":"سپس دلار در بانک های خارج از ایالات متحده سپرده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755690.mp3"},{"sentence":"I paid/put $100 into his account.","translation":"من 100 دلار به حسابش پرداخت کردم/وارد کردم.","audio_url":null},{"sentence":"You should put your valuables in the hotel safe.","translation":"شما باید اشیای قیمتی خود را در گاوصندوق هتل بگذارید.","audio_url":null}]'::jsonb,4),
('a0f94f7b-f081-55d8-8e4d-78eaa9320abd','32d50184-f239-59d8-a3ff-7000650b6ba3',1,null,null,'spoken & written','to have earned something by good or bad actions or behaviour',null,null,'مستحق بودن، لایق بودن (خوب یا بد)','{}'::text[],'{}'::text[],array['deserve a rest/break/holiday etc Once the students have done their exams they deserve a break.','deserve a chance Everybody deserves a second chance.','deserve respect Our police officers deserve our respect.','deserve credit/praise The team played really well and they deserve credit for it.','deserve support This is a splendid proposal which deserves our support.','deserve recognition (= public respect and thanks ) The teaching profession deserves more recognition.','deserve better ( also deserve a better deal ) (= deserve to be treated better or to be in a better situation ) They treated him badly at work and I thought he deserved better.','deserve a (special) mention (= used especially in speeches to mention someone''s good work or actions ) Richard deserves a special mention for all his hard work on this project.','deserve a place You need top grades to deserve a place at the best universities.','deserve punishment If you commit a crime, you have deserved punishment.','thoroughly/fully deserve something He didn''t work so he thoroughly deserved his poor marks.','richly deserve something (= greatly deserve something good that happens ) Her success was richly deserved.','well deserved The restaurant has a well deserved reputation for excellent fish.','get what you deserve (= experience something bad after you have behaved badly ) I like films where the bad guys get what they deserve.','deserve all/everything you get (= deserve any bad things that happen to you ) She''s behaved really stupidly and she deserves all she gets.']::text[],'[{"sentence":"What have I done to deserve this?","translation":"من چه کرده ام که لایق این باشم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716395.mp3"},{"sentence":"We didn’t deserve to win.","translation":"ما مستحق برد نبودیم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001137572.mp3"},{"sentence":"the success he so richly deserves","translation":"موفقیتی که او بسیار سزاوار آن است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830493.mp3"},{"sentence":"I’m sorry for the kids. They deserve better (= deserve to be treated in a better way ) .","translation":"برای بچه ها متاسفم آنها سزاوار بهتری هستند (= سزاوار رفتار بهتر با آنهاست).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830494.mp3"},{"sentence":"I think we deserve a rest after all that hard work.","translation":"فکر می‌کنم پس از این همه کار سخت، شایسته استراحت هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716402.mp3"},{"sentence":"Ledley deserves a place in the team.","translation":"لدلی شایسته حضور در تیم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716403.mp3"},{"sentence":"Paula deserves a special mention for all the help she has given us.","translation":"پائولا به خاطر تمام کمک هایی که به ما کرده است شایسته تذکر ویژه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716409.mp3"},{"sentence":"I would never hit anyone, even if they deserved it.","translation":"من هرگز کسی را نمی زنم، حتی اگر لیاقتش را داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001137575.mp3"},{"sentence":"What has he done to deserve this punishment ?","translation":"او چه کرده است که مستحق این مجازات است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716418.mp3"},{"sentence":"He deserves all he gets for being so dishonest.","translation":"او سزاوار تمام چیزی است که به خاطر بی صداقتی به دست می آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716424.mp3"},{"sentence":"People who are sent to prison for drunk-driving get what they deserve .","translation":"افرادی که به دلیل رانندگی در حالت مستی به زندان فرستاده می شوند آنچه را که لیاقتش را دارند به دست می آورند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716425.mp3"},{"sentence":"She deserves a prize.","translation":"او شایسته جایزه است.","audio_url":null}]'::jsonb,12),
('575d59ea-8272-5f3a-a256-b593d63fe4f4','32d50184-f239-59d8-a3ff-7000650b6ba3',2,null,null,'spoken & written',null,null,'deserve consideration/attention etc','مستحق بودن، لایق بودن (خوب یا بد)','{}'::text[],'{}'::text[],array['deserve a rest/break/holiday etc Once the students have done their exams they deserve a break.','deserve a chance Everybody deserves a second chance.','deserve respect Our police officers deserve our respect.','deserve credit/praise The team played really well and they deserve credit for it.','deserve support This is a splendid proposal which deserves our support.','deserve recognition (= public respect and thanks ) The teaching profession deserves more recognition.','deserve better ( also deserve a better deal ) (= deserve to be treated better or to be in a better situation ) They treated him badly at work and I thought he deserved better.','deserve a (special) mention (= used especially in speeches to mention someone''s good work or actions ) Richard deserves a special mention for all his hard work on this project.','deserve a place You need top grades to deserve a place at the best universities.','deserve punishment If you commit a crime, you have deserved punishment.','thoroughly/fully deserve something He didn''t work so he thoroughly deserved his poor marks.','richly deserve something (= greatly deserve something good that happens ) Her success was richly deserved.','well deserved The restaurant has a well deserved reputation for excellent fish.','get what you deserve (= experience something bad after you have behaved badly ) I like films where the bad guys get what they deserve.','deserve all/everything you get (= deserve any bad things that happen to you ) She''s behaved really stupidly and she deserves all she gets.']::text[],'[]'::jsonb,0),
