('f75d9541-dfbd-5004-ad89-e3d301728f45','a97230c8-936e-5ba5-a932-0c7f68793196',1,'grow','رشد کنند','spoken & written','to grow or change into something bigger, stronger, or more advanced , or to make someone or something do this','[ intransitive, transitive ]',null,'رشد کردن، بالیدن؛ توسعه دادن؛ گرفتار شدن (بیماری)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Knowledge in the field of genetics has been developing very rapidly.","translation":"دانش در زمینه ژنتیک بسیار سریع در حال توسعه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139449.mp3"},{"sentence":"Corsica has developed its economy around the tourist industry.","translation":"کورس اقتصاد خود را حول صنعت توریست توسعه داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001985180.mp3"},{"sentence":"Chicago developed into a big city in the late 1800s.","translation":"شیکاگو در اواخر دهه 1800 به یک شهر بزرگ تبدیل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139452.mp3"},{"sentence":"It’s hard to believe that a tree can develop from a small seed.","translation":"باورش سخت است که یک درخت بتواند از یک دانه کوچک رشد کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139455.mp3"},{"sentence":"exercises to develop muscle strength","translation":"تمریناتی برای تقویت قدرت عضلانی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139458.mp3"}]'::jsonb,5),
('64aad452-0081-5dbe-ae90-05eef516e28f','a97230c8-936e-5ba5-a932-0c7f68793196',2,'new idea/product','ایده/محصول جدید','spoken & written','to design or make a new idea, product , system etc over a period of time','[ transitive ]',null,'برای طراحی یا ساخت یک ایده، محصول، سیستم و غیره جدید در یک دوره زمانی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Scientists are developing new drugs to treat arthritis.","translation":"دانشمندان در حال توسعه داروهای جدید برای درمان آرتروز هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139466.mp3"},{"sentence":"She should have developed her own style instead of copying him.","translation":"او باید به جای تقلید از او سبک خودش را توسعه می داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743637.mp3"},{"sentence":"Researchers are developing technology for the US military.","translation":"محققان در حال توسعه فناوری برای ارتش آمریکا هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743640.mp3"}]'::jsonb,3),
('280d65a6-b7d7-552c-a4e2-87d58f9f9543','a97230c8-936e-5ba5-a932-0c7f68793196',3,'feeling','احساس','spoken & written','to start to have a feeling or quality that then becomes stronger','[ transitive ]',null,'برای شروع به داشتن یک احساس یا کیفیت که سپس قوی تر می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He had developed a certain affection for me.","translation":"او علاقه خاصی به من پیدا کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743646.mp3"},{"sentence":"The children are beginning to develop a sense of responsibility.","translation":"کودکان شروع به پرورش احساس مسئولیت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743649.mp3"},{"sentence":"It was in college that he developed a taste for (= started to like ) rugby football.","translation":"در کالج بود که او به فوتبال راگبی (= شروع به دوست داشتن) کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743650.mp3"}]'::jsonb,3),
('79a79201-a09f-5f57-91ff-709ac447419a','a97230c8-936e-5ba5-a932-0c7f68793196',4,'skill/ability','مهارت/توانایی','spoken & written','if you develop a skill or ability , or if it develops, it becomes stronger or more advanced','[ intransitive, transitive ]',null,'اگر یک مهارت یا توانایی را توسعه دهید، یا اگر آن را توسعه دهید، قوی تر یا پیشرفته تر می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The course is designed to help students develop their speaking skills.","translation":"این دوره برای کمک به دانش آموزان در توسعه مهارت های گفتاری خود طراحی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743660.mp3"}]'::jsonb,1),
('d58cbc19-e094-56b1-83c4-5beca05b43a7','a97230c8-936e-5ba5-a932-0c7f68793196',5,'disease','بیماری','spoken & written','if you develop a disease or illness , or if it develops, you start to have it','[ intransitive, transitive ]',null,'اگر به بیماری یا بیماری مبتلا شوید، یا در صورت بروز آن، شروع به ابتلا به آن می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Some alcoholics develop liver disease.","translation":"برخی از الکلی ها به بیماری کبدی مبتلا می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001139473.mp3"},{"sentence":"Pneumonia can develop very quickly.","translation":"پنومونی می تواند خیلی سریع ایجاد شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743662.mp3"}]'::jsonb,2),
('9c2431dd-d911-5539-ba97-8dcec2e6708c','a97230c8-936e-5ba5-a932-0c7f68793196',6,'fault/problem','خطا/مشکل','spoken & written','to begin to have a physical fault','[ transitive ]',null,'شروع به داشتن یک نقص فیزیکی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The oil tank had developed a small crack.","translation":"مخزن نفت یک ترک کوچک ایجاد کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743668.mp3"},{"sentence":"The plane developed engine trouble and was forced to land.","translation":"موتور هواپیما دچار مشکل شد و مجبور به فرود شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743669.mp3"}]'::jsonb,2),
