('87aa41ea-afa4-5a8e-8a72-72a25f9030fb','855a112a-35a7-5396-a54f-a9f0f99db524',1,null,null,'spoken & written','to say that something such as a fact or idea is not correct or true','[ transitive ]',null,'گفتن اینکه چیزی مانند یک واقعیت یا ایده صحیح یا درست نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The main facts of the book have never been disputed.","translation":"حقایق اصلی کتاب هرگز مورد مناقشه قرار نگرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001717514.mp3"},{"sentence":"Few would dispute that travel broadens the mind.","translation":"کمتر کسی مخالف این است که سفر ذهن را وسعت می بخشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001717517.mp3"}]'::jsonb,2),
('e6a8227e-1f28-5fc7-b627-7b5e8345bc13','855a112a-35a7-5396-a54f-a9f0f99db524',2,null,null,'formal','to argue or disagree with someone','[ intransitive, transitive ]',null,'بحث کردن یا مخالفت کردن با کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Hazlitt, though much younger, was soon disputing with Wordsworth on equal terms.","translation":"هازلیت، اگرچه بسیار جوان‌تر بود، اما به زودی با وردزورث در شرایط مساوی بحث کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001717519.mp3"},{"sentence":"What happened next is hotly disputed .","translation":"آنچه بعد اتفاق افتاد به شدت مورد مناقشه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001717520.mp3"}]'::jsonb,2),
('ca4800c5-e7f1-522d-93db-92829f34a07d','855a112a-35a7-5396-a54f-a9f0f99db524',3,null,null,'spoken & written','to try to get control of something or win something','[ transitive ]',null,'تلاش برای کنترل چیزی یا برنده شدن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Soviet forces disputed every inch of ground.","translation":"نیروهای شوروی هر وجب از زمین را مورد مناقشه قرار دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000807844.mp3"}]'::jsonb,1),
('344a746a-89be-517a-ac51-a556423cef81','cc7c868c-46c4-53b5-a543-c98b6d1d64d7',1,'far away','خیلی دور','spoken & written','far away in space or time',null,null,'دور، پرتو؛ سرد و بی‌اعتنا (برخورد)','{}'::text[],'{}'::text[],array['the distant past/future (= a long time in the past/future ) It is a fictional story set in the distant past. In the distant future, there may be a cure for the disease.','a distant memory (= something that happened a long time ago ) Already the summer seemed like a distant memory.','distant mountains/hills From here, you can look out to the distant hills.','a distant planet/galaxy/star They saw telescope images of the distant planet Neptune.','a distant sound Sometimes you can hear the distant sound of traffic from the main road.','distant thunder Distant thunder rumbled over the mountains.','distant places She loved the wild, distant places of Scotland.','a distant land literary (= a country that is a long way away ) He fled to a distant land.','in the dim and distant past humorous (= a long time ago ) Back in the dim and distant past when I was at school, computers didn’t exist.','in the not too distant future (= quite soon ) We’re expecting a final decision in the not too distant future.']::text[],'[{"sentence":"the sound of distant gunfire","translation":"صدای تیراندازی از راه دور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001147675.mp3"},{"sentence":"Her honeymoon seemed a distant memory .","translation":"ماه عسل او خاطره ای دور به نظر می رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690581.mp3"},{"sentence":"That affair was in the dim and distant past (= a long time ago ) .","translation":"آن ماجرا در گذشته های دور و تاریک (= خیلی وقت پیش) بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690585.mp3"},{"sentence":"The president hopes to visit Ireland in the not too distant future (= quite soon ) .","translation":"رئیس جمهور امیدوار است در آینده ای نه چندان دور (= خیلی زود) از ایرلند دیدن کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690590.mp3"},{"sentence":"stars that are distant from our galaxy","translation":"ستاره هایی که از کهکشان ما دور هستند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690597.mp3"}]'::jsonb,5),
