('37a41f2f-1c2d-5c97-8766-b61b0bcb4b53','cc7c868c-46c4-53b5-a543-c98b6d1d64d7',5,null,null,'spoken & written',null,null,'distant from something','دور، پرتو؛ سرد و بی‌اعتنا (برخورد)','{}'::text[],'{}'::text[],array['the distant past/future (= a long time in the past/future ) It is a fictional story set in the distant past. In the distant future, there may be a cure for the disease.','a distant memory (= something that happened a long time ago ) Already the summer seemed like a distant memory.','distant mountains/hills From here, you can look out to the distant hills.','a distant planet/galaxy/star They saw telescope images of the distant planet Neptune.','a distant sound Sometimes you can hear the distant sound of traffic from the main road.','distant thunder Distant thunder rumbled over the mountains.','distant places She loved the wild, distant places of Scotland.','a distant land literary (= a country that is a long way away ) He fled to a distant land.','in the dim and distant past humorous (= a long time ago ) Back in the dim and distant past when I was at school, computers didn’t exist.','in the not too distant future (= quite soon ) We’re expecting a final decision in the not too distant future.']::text[],'[]'::jsonb,0),
('5e6221d6-a785-5144-bd14-07806c53726b','753e2786-fd23-5fa2-add6-7aab98dde57c',1,'interrupt','قطع کردن','spoken & written','to interrupt someone so that they cannot continue what they are doing',null,null,'مزاحم شدن، آسودگی بر هم زدن؛ مشغله داشتن (ذهن)','{}'::text[],'{}'::text[],array['disturb somebody''s sleep Local people said their sleep was being disturbed by the noise from the aircraft.','disturb somebody''s concentration I couldn''t work with the kids around disturbing my concentration.','disturb somebody''s thoughts A gentle knock on the door disturbed his thoughts.','sorry to disturb you spoken (= said to apologize for interrupting what someone is doing ) Sorry to disturb you, but could you sign this letter, please?']::text[],'[{"sentence":"Sorry to disturb you , but I have an urgent message.","translation":"ببخشید مزاحم شما شدم، اما یک پیام فوری دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001148564.mp3"},{"sentence":"The thieves fled when they were disturbed by a neighbour.","translation":"سارقان با مزاحمت همسایه متواری شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690658.mp3"},{"sentence":"Do not disturb (= a sign you put on a door so that people will not interrupt you ) .","translation":"مزاحم نشوید (= علامتی که بر در می گذارید تا مردم حرف شما را قطع نکنند) .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690659.mp3"}]'::jsonb,3),
('d2e13f2d-23d9-54e1-a5e6-5f6308caf62b','753e2786-fd23-5fa2-add6-7aab98dde57c',2,'worry','نگرانی','spoken & written','to make someone feel worried or upset',null,null,'ایجاد احساس نگرانی یا ناراحتی در کسی','{}'::text[],'{}'::text[],array['disturb somebody''s sleep Local people said their sleep was being disturbed by the noise from the aircraft.','disturb somebody''s concentration I couldn''t work with the kids around disturbing my concentration.','disturb somebody''s thoughts A gentle knock on the door disturbed his thoughts.','sorry to disturb you spoken (= said to apologize for interrupting what someone is doing ) Sorry to disturb you, but could you sign this letter, please?']::text[],'[{"sentence":"What disturbs you most about this latest development?","translation":"چه چیزی در مورد این آخرین توسعه بیشتر شما را ناراحت می کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690664.mp3"}]'::jsonb,1),
('4483d393-7188-5b63-8941-4eea383d5af7','753e2786-fd23-5fa2-add6-7aab98dde57c',3,'move','حرکت کنید','spoken & written','to move something or change its position',null,null,'حرکت دادن چیزی یا تغییر موقعیت آن','{}'::text[],'{}'::text[],array['disturb somebody''s sleep Local people said their sleep was being disturbed by the noise from the aircraft.','disturb somebody''s concentration I couldn''t work with the kids around disturbing my concentration.','disturb somebody''s thoughts A gentle knock on the door disturbed his thoughts.','sorry to disturb you spoken (= said to apologize for interrupting what someone is doing ) Sorry to disturb you, but could you sign this letter, please?']::text[],'[{"sentence":"If you find a bird’s nest, never disturb the eggs.","translation":"اگر لانه پرنده ای پیدا کردید، هرگز تخم ها را مزاحم نکنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001148576.mp3"},{"sentence":"I promise not to disturb anything .","translation":"قول میدم مزاحم چیزی نشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829632.mp3"}]'::jsonb,2),
('5f562f8a-3742-5d4b-ab78-d2d9c9331b5c','753e2786-fd23-5fa2-add6-7aab98dde57c',4,'change','تغییر دهید','spoken & written','to change a normal situation in a way that causes problems',null,null,'برای تغییر یک وضعیت عادی به گونه ای که باعث ایجاد مشکل شود','{}'::text[],'{}'::text[],array['disturb somebody''s sleep Local people said their sleep was being disturbed by the noise from the aircraft.','disturb somebody''s concentration I couldn''t work with the kids around disturbing my concentration.','disturb somebody''s thoughts A gentle knock on the door disturbed his thoughts.','sorry to disturb you spoken (= said to apologize for interrupting what someone is doing ) Sorry to disturb you, but could you sign this letter, please?']::text[],'[{"sentence":"My hormone balance is disturbed by my pregnancy.","translation":"تعادل هورمونی من به دلیل بارداری به هم می خورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690670.mp3"},{"sentence":"New procedures often disturb the comfortable habits of the workforce.","translation":"رویه های جدید اغلب عادات راحت نیروی کار را مختل می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690671.mp3"}]'::jsonb,2),
('6fd8c11a-b6cd-5dda-bc14-7ad172ecd35d','753e2786-fd23-5fa2-add6-7aab98dde57c',5,null,null,'spoken & written',null,null,'disturb the peace','مزاحم شدن، آسودگی بر هم زدن؛ مشغله داشتن (ذهن)','{}'::text[],'{}'::text[],array['disturb somebody''s sleep Local people said their sleep was being disturbed by the noise from the aircraft.','disturb somebody''s concentration I couldn''t work with the kids around disturbing my concentration.','disturb somebody''s thoughts A gentle knock on the door disturbed his thoughts.','sorry to disturb you spoken (= said to apologize for interrupting what someone is doing ) Sorry to disturb you, but could you sign this letter, please?']::text[],'[]'::jsonb,0),
('1755f949-ee9f-5c01-a434-014908b3f48f','e4779574-f07b-5706-919b-41ab4201cd9a',1,null,null,'spoken & written','the legal ending of a marriage','[ countable, uncountable ]',null,'طلاق، جدایی (حقوقی)','{}'::text[],'{}'::text[],array['get a divorce (= end your marriage ) Their marriage had never been happy and in the end they got a divorce.','go through a divorce (= experience getting a divorce ) I was going through a divorce and it was a very painful time.','want a divorce She told him she wanted a divorce.','ask (somebody) for a divorce She asked her husband for a divorce after he had been unfaithful.','a marriage ends in divorce Five years later, their marriage ended in divorce.','file for divorce ( also petition for divorce formal ) (= start the legal divorce process ) The next day I saw a lawyer and filed for a divorce.','a bitter divorce (= involving very angry feelings ) After a long and bitter divorce, Wendy was looking forward to starting a new life.','a messy divorce (= complicated and unpleasant to deal with ) She wanted to avoid a messy divorce .','a painful divorce (= causing a lot of sadness ) I have been through a painful divorce, and know what it feels like.','the divorce rate (= the number of people who get a divorce ) The country has a high divorce rate.','divorce proceedings (= the legal processes of getting a divorce ) His first marriage was unsuccessful and led to long divorce proceedings.','a divorce settlement (= the amount of money, property etc each person gets in a divorce ) She received a $10 million divorce settlement from her first husband.','a divorce case (= a legal case dealing with a divorce ) It was the biggest divorce case that an English court has dealt with.','a divorce lawyer/court (= one dealing with divorce ) She''s a famous New York divorce lawyer.','divorce papers (= documents concerning a divorce ) My husband refused to sign the divorce papers.','grounds for divorce (= acceptable reasons for divorce, according to the law ) Violence and neglect are grounds for divorce.']::text[],'[{"sentence":"Why doesn’t she get a divorce ?","translation":"چرا طلاق نمی گیرد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000810233.mp3"},{"sentence":"One in three marriages ends in divorce .","translation":"از هر سه ازدواج یک نفر به طلاق ختم می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000186978.mp3"},{"sentence":"His wife has started divorce proceedings .","translation":"همسرش پرونده طلاق را آغاز کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829719.mp3"},{"sentence":"the rise in the divorce rate","translation":"افزایش آمار طلاق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829723.mp3"},{"sentence":"She received the house as part of the divorce settlement (= the amount of money, property etc each person receives in a divorce case ) .","translation":"او خانه را به عنوان بخشی از توافق طلاق (= مقدار پول، اموال و غیره هر فرد در یک پرونده طلاق دریافت می کند) دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001689126.mp3"},{"sentence":"The Act extended the grounds (= legal reasons ) for divorce .","translation":"این قانون زمینه (= دلایل قانونی) طلاق را گسترش داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00286.mp3"}]'::jsonb,6),
('d507532c-e615-5b06-8317-aedab01bee82','e4779574-f07b-5706-919b-41ab4201cd9a',2,null,null,'formal','the fact of separating two related things','[ countable usually singular ]',null,'واقعیت جدا کردن دو چیز مرتبط','{}'::text[],'{}'::text[],array['get a divorce (= end your marriage ) Their marriage had never been happy and in the end they got a divorce.','go through a divorce (= experience getting a divorce ) I was going through a divorce and it was a very painful time.','want a divorce She told him she wanted a divorce.','ask (somebody) for a divorce She asked her husband for a divorce after he had been unfaithful.','a marriage ends in divorce Five years later, their marriage ended in divorce.','file for divorce ( also petition for divorce formal ) (= start the legal divorce process ) The next day I saw a lawyer and filed for a divorce.','a bitter divorce (= involving very angry feelings ) After a long and bitter divorce, Wendy was looking forward to starting a new life.','a messy divorce (= complicated and unpleasant to deal with ) She wanted to avoid a messy divorce .','a painful divorce (= causing a lot of sadness ) I have been through a painful divorce, and know what it feels like.','the divorce rate (= the number of people who get a divorce ) The country has a high divorce rate.','divorce proceedings (= the legal processes of getting a divorce ) His first marriage was unsuccessful and led to long divorce proceedings.','a divorce settlement (= the amount of money, property etc each person gets in a divorce ) She received a $10 million divorce settlement from her first husband.','a divorce case (= a legal case dealing with a divorce ) It was the biggest divorce case that an English court has dealt with.','a divorce lawyer/court (= one dealing with divorce ) She''s a famous New York divorce lawyer.','divorce papers (= documents concerning a divorce ) My husband refused to sign the divorce papers.','grounds for divorce (= acceptable reasons for divorce, according to the law ) Violence and neglect are grounds for divorce.']::text[],'[{"sentence":"the divorce between theory and method","translation":"طلاق بین نظریه و روش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000810257.mp3"}]'::jsonb,1),
('589ae944-8498-5d2e-9321-b9fbd8706ef1','977f50bd-31b7-58f5-be7f-6008ea663995',1,null,null,'spoken & written','if someone divorces their husband or wife , or if two people divorce, they legally end their marriage','[ intransitive, transitive ]',null,'اگر شخصی از زن یا شوهر خود طلاق بگیرد یا دو نفر طلاق بگیرند، به طور قانونی به ازدواج خود پایان می دهند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"David’s parents divorced when he was six.","translation":"پدر و مادر دیوید در شش سالگی از هم جدا شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000810268.mp3"},{"sentence":"My father threatened to divorce her.","translation":"پدرم او را تهدید به طلاق کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001689139.mp3"}]'::jsonb,2),
('ce777163-85b4-59f2-b663-196e01240e83','977f50bd-31b7-58f5-be7f-6008ea663995',2,null,null,'formal','to separate two ideas, subjects etc completely','[ transitive ]',null,'برای جدا کردن دو ایده، موضوع و غیره به طور کامل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It is difficult to divorce sport from politics.","translation":"جدا کردن ورزش از سیاست دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000810275.mp3"}]'::jsonb,1),
('19b821a9-d17e-5b0a-bc3e-26aaac46e063','977f50bd-31b7-58f5-be7f-6008ea663995',3,null,null,'spoken & written','to stop being involved in an activity , organization , situation etc','[ transitive ]',null,'توقف درگیر شدن در یک فعالیت، سازمان، موقعیت و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our society has divorced itself from religion.","translation":"جامعه ما خود را از دین جدا کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001689148.mp3"}]'::jsonb,1),
('4831035e-946e-5b68-8c54-038fea8d525c','9db33e73-9d54-5dfe-8387-1f5f6abe0566',1,null,null,'spoken & written','a picture that you draw with a pencil , pen etc','[ countable ]',null,'نقاشی، کشیده (با مداد)','{}'::text[],'{}'::text[],array['do/make a drawing Sammy was doing a drawing of his sister.','a drawing shows something The drawing showed a castle surrounded by woods.','a detailed drawing He made detailed drawings of animals and flowers.','a line drawing (= consisting only of lines ) The front cover had a line drawing of a girl on the beach.','a pencil/ink/charcoal etc drawing (= done using a pencil, ink etc ) I like to do a few pencil drawings when I go away anywhere.','a scale drawing (= showing the correct relative sizes of things ) The architect made a scale drawing of the new room.']::text[],'[{"sentence":"a drawing of Canterbury Cathedral","translation":"نقاشی از کلیسای جامع کانتربری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000798541.mp3"}]'::jsonb,1),
('37b9d978-d797-543b-8269-b249c562ce7e','9db33e73-9d54-5dfe-8387-1f5f6abe0566',2,null,null,'spoken & written','the art or skill of making pictures, plans etc with a pen or pencil','[ uncountable ]',null,'هنر یا مهارت ساختن تصاویر، طرح ها و غیره با خودکار یا مداد','{}'::text[],'{}'::text[],array['do/make a drawing Sammy was doing a drawing of his sister.','a drawing shows something The drawing showed a castle surrounded by woods.','a detailed drawing He made detailed drawings of animals and flowers.','a line drawing (= consisting only of lines ) The front cover had a line drawing of a girl on the beach.','a pencil/ink/charcoal etc drawing (= done using a pencil, ink etc ) I like to do a few pencil drawings when I go away anywhere.','a scale drawing (= showing the correct relative sizes of things ) The architect made a scale drawing of the new room.']::text[],'[{"sentence":"I’ve never been very good at drawing.","translation":"من هرگز در طراحی خیلی خوب نبودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000798547.mp3"}]'::jsonb,1),
('7fe5d35d-889b-58c6-867d-d09ee6bb5aac','9db33e73-9d54-5dfe-8387-1f5f6abe0566',3,null,null,'spoken & written','a competition in which people whose names or tickets are chosen by chance win money or prizes','[ countable ]',null,'مسابقه ای که در آن افرادی که نام یا بلیط آنها به طور تصادفی انتخاب شده است برنده پول یا جایزه می شوند','{}'::text[],'{}'::text[],array['do/make a drawing Sammy was doing a drawing of his sister.','a drawing shows something The drawing showed a castle surrounded by woods.','a detailed drawing He made detailed drawings of animals and flowers.','a line drawing (= consisting only of lines ) The front cover had a line drawing of a girl on the beach.','a pencil/ink/charcoal etc drawing (= done using a pencil, ink etc ) I like to do a few pencil drawings when I go away anywhere.','a scale drawing (= showing the correct relative sizes of things ) The architect made a scale drawing of the new room.']::text[],'[{"sentence":"The church social will include a buffet dinner and a prize drawing .","translation":"مراسم اجتماعی کلیسا شامل یک شام بوفه و یک قرعه کشی جایزه خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758377.mp3"}]'::jsonb,1)
